    ("upkeep", "parvarishlash, yaxshi holatda saqlash", "B1", "33", "The upkeep of the garden takes hours every week."),
    ("complimentary", "free; given out of kindness", "B1", "33", "The hotel offered a complimentary breakfast every morning."),
    ("deprive", "mahrum qilmoq", "B1", "33", "Losing his phone deprived him of sleep all night."),
    ("disregard", "ignore", "B1", "33", "He disregarded the warning sign and touched the wet paint."),
    ("scold", "so'kmoq", "B1", "33", "Mom scolded the puppy for chewing her shoes."),
    ("remonstrance", "scolding - so'kish", "B1", "33", "His remonstrance about the mess lasted ten minutes."),
    ("overpower", "kuchli bo'lmoq", "B1", "33", "The smell of garlic overpowered everything in the kitchen."),
