    ("overrun", "spread quickly", "B1", "33", "Weeds overran the garden while they were on vacation."),
    ("condiments", "spices", "B1", "33", "The table had ketchup and other condiments for the fries."),
    ("in moderation", "meyorida", "B1", "33", "Eat sweets in moderation, not the whole box."),
    ("excrete", "uzmoq, ajratmoq", "B1", "33", "The plant excretes a sticky liquid when touched."),
    ("enterprising", "tashabusskor, uddaburon", "B1", "33", "The enterprising kid sold lemonade to earn pocket money."),
