    ("hasten", "go faster, move faster", "B1", "33", "She hastened home when the sky turned dark."),
    ("hurtle", "rush or fly violently", "B1", "33", "The sled hurtled down the icy hill."),
    ("whiz", "go extremely fast", "B1", "33", "The scooter whizzed past us in seconds."),
    ("lax", "inattentive, not careful", "B1", "33", "The guard was lax and let the cat sneak in."),
    ("diversions", "leisure activities", "B1", "33", "Reading and chess are his favorite diversions."),
