    # ---- Unit 35 (B2) ----
    ("abase", "xo'rlamoq, kamsitmoq", "B2", "35", "(v.) to humiliate, degrade (After being overthrown and abased, the deposed leader offered to bow down to his conqueror.)"),
    ("abate", "kamaymoq, susaymoq", "B2", "35", "(v.) to reduce, lessen (The rain poured down for a while, then abated.)"),
    ("abduct", "o'g'irlab ketmoq (odamni)", "B2", "35", "(v.) to kidnap, take by force (The evildoers abducted the fairy princess from her happy home.)"),
    ("aberration", "me'yordan chetlanish", "B2", "35", "(n.) something that differs from the norm (In 1918, the Boston Red Sox won the World Series, but the success turned out to be an aberration, and the Red Sox have not won a World Series since.)"),
    ("abet", "yordam bermoq, gij-gijlamoq", "B2", "35", "(v.) to aid, help, encourage (The spy succeeded only because he had a friend on the inside to abet him.)"),
    ("abdicate", "taxtdan/lavozimdan voz kechmoq", "B2", "35", "(v.) to give up a position, usually one of leadership (When he realized that the revolutionaries would surely win, the king abdicated his throne.)"),
    ("abject", "ayanchli, xor", "B2", "35", "(adj.) wretched, pitiful (After losing all her money, falling into a puddle, and breaking her ankle, Eloise was abject.)"),
    ("abjure", "rad etmoq, tonmoq", "B2", "35", "(v.) to reject, renounce (To prove his honesty, the President abjured the evil policies of his wicked predecessor.)"),
    ("abnegation", "o'zini tiyish, zohidlik", "B2", "35", "(n.) denial of comfort to oneself (The holy man slept on the floor, took only cold showers, and generally followed other practices of abnegation.)"),
    ("abort", "yarim yo'lda to'xtatmoq", "B2", "35", "(v.) to give up on a half-finished project or effort (After they ran out of food, the men, attempting to jump rope around the world, had to abort and go home.)"),
    ("abridge", "qisqartirmoq", "B2", "35", "1. (v.) to cut down, shorten (The publisher thought the dictionary was too long and abridged it.) 2. (adj.) shortened (Moby-Dick is such a long book that even the abridged version is longer than most normal books.)"),
    ("abrogate", "bekor qilmoq (rasman)", "B2", "35", "(v.) to abolish, usually by authority (The Bill of Rights assures that the government cannot abrogate our right to a free press.)"),
    ("abscond", "yashirincha qochib ketmoq", "B2", "35", "(v.) to sneak away and hide (In the confusion, the super-spy absconded into the night with the secret plans.)"),
    ("absolution", "gunohdan forig' etish, oqlash", "B2", "35", "(n.) freedom from blame, guilt, sin (Once all the facts were known, the jury gave Angela absolution by giving a verdict of not guilty.)"),
    ("abstain", "o'zini tiymoq, saqlanmoq", "B2", "35", "(v.) to freely choose not to commit an action (Everyone demanded that Angus put on the kilt, but he did not want to do it and abstained.)"),
    ("abstruse", "tushunish qiyin, murakkab", "B2", "35", "(adj.) hard to comprehend (Everyone else in the class understood geometry easily, but John found the subject abstruse.)"),
    ("accentuate", "urg'u bermoq, ta'kidlamoq", "B2", "35", "(v.) to stress, highlight (Psychologists agree that those people who are happiest accentuate the positive in life.)"),
    ("acclaim", "olqishlamoq; olqish", "B2", "35", "(n.) high praise (Greg’s excellent poem won the acclaim of his friends.)"),
    ("accolade", "mukofot, e'tirof", "B2", "35", "(n.) high praise, special distinction (Everyone offered accolades to Sam after he won the Noble Prize.)"),
    ("accommodating", "iltifotli, yon bosuvchi", "B2", "35", "(adj.) helpful, obliging, polite (Though the apartment was not big enough for three people, Arnold, Mark, and Zebulon were all friends and were accommodating to each other.)"),
    ("accord", "kelishuv, ahd", "B2", "35", "(n.) an agreement (After much negotiating, England and Iceland finally came to a mutually beneficial accord about fishing rights off the cost of Greenland.)"),
    ("accost", "yo'lini to'sib gap qotmoq", "B2", "35", "(v.) to confront verbally (Though Antoinette was normally quite calm, when the waiter spilled soup on her for the fourth time in 15 minutes she stood up and accosted the man.)"),
    ("accretion", "asta-sekin o'sish, qatlanish", "B2", "35", "(n.) slow growth in size or amount (Stalactites are formed by the accretion of minerals from the roofs of caves.)"),
    ("acerbic", "achchiq, zaharxanda", "B2", "35", "(adj.) biting, bitter in tone or taste (Jill became extremely acerbic and began to cruelly make fun of all her friends.)"),
    ("acquiesce", "indamay rozi bo'lmoq", "B2", "35", "(v.) to agree without protesting (Though Mr. Correlli wanted to stay outside and work in his garage, when his wife told him that he had better come in to dinner, he acquiesced to her demands.)"),
    ("acumen", "o'tkir zehn, farosat", "B2", "35", "(n.) keen insight (Because of his mathematical acumen, Larry was able to figure out in minutes problems that took other students hours.)"),
    ("adamant", "qat'iy, bo'yin egmas", "B2", "35", "(adj.) impervious, immovable, unyielding (Though public pressure was intense, the President remained adamant about his proposal.)"),
    ("adept", "mohir, usta", "B2", "35", "(adj.) extremely skilled (Tarzan was adept at jumping from tree to tree like a monkey.)"),
    ("acrimony", "achchiqlik, adovat", "B2", "35", "(n.) bitterness, discord (Though they vowed that no girl would ever come between them, Biff and Trevor could not keep acrimony from overwhelming their friendship after they both fell in love with the lovely Teresa.)"),
    ("adhere", "yopishmoq; sodiq qolmoq", "B2", "35", "1. (n.) to stick to something (We adhered the poster to the wall with tape.) 2. (n.) to follow devoutly (He adhered to the dictates of his religion without question.)"),
    ("adorn", "bezamoq", "B2", "35", "(v.) to decorate (We adorned the tree with ornaments.)"),
    ("adroit", "chaqqon, epchil", "B2", "35", "(adj.) skillful, dexterous (The adroit thief could pick someone’s pocket without attracting notice.)"),
    ("adulation", "haddan ortiq maqtov, xushomad", "B2", "35", "(n.) extreme praise (Though the book was pretty good, Marcy did not believe it deserved the adulation it received.)"),
    ("adumbrate", "xira ishora qilmoq, chizgilamoq", "B2", "35", "(v.) to sketch out in a vague way (The coach adumbrated a game plan, but none of the players knew precisely what to do.)"),
    # ---- Unit 36 (B2) ----
    ("aesthetic", "go'zallikka oid, estetik", "B2", "36", "(adj.) artistic, related to the appreciation of beauty (We hired Susan as our interior decorator because she has such a fine aesthetic sense.)"),
    ("affable", "xushmuomala, ochiq yuzli", "B2", "36", "(adj.) friendly, amiable (People like to be around George because he is so affable and good-natured.)"),
    ("affinity", "yaqinlik, moyillik", "B2", "36", "(n.)a spontaneous feeling of closeness (Jerry didn’t know why, but he felt an incredible affinity for Kramer the first time they met.)"),
    ("affront", "haqorat, izzatga tegish", "B2", "36", "(n.) an insult (Bernardo was very touchy, and took any slight as an affront to his honor.)"),
    ("aggrandize", "bo'rttirib ulug'lamoq, kuchaytirmoq", "B2", "36", "(v.) to increase or make greater (Joseph always dropped the names of the famous people his father knew as a way to aggrandize his personal stature.)"),
    ("aggrieved", "xafa bo'lgan, jabrlangan", "B2", "36", "(adj.) distressed, wronged, injured (The foreman mercilessly overworked his aggrieved employees.)"),
    ("agile", "chaqqon, harakatchan", "B2", "36", "(adj.) quick, nimble (The dogs were too slow to catch the agile rabbit.)"),
    ("agnostic", "agnostik, xudo borligiga shubha qiluvchi", "B2", "36", "(adj.) believing that the existence of God cannot be proven or disproven (Joey’s parents are very religious, but he is agnostic.)"),
    ("agriculture", "qishloq xo'jaligi, dehqonchilik", "B2", "36", "(n.) farming (It was a huge step in the progress of civilization when tribes left hunting and gathering and began to develop more sustainable methods of obtaining food, such as agriculture.)"),
    ("alacrity", "jonbozlik, chaqqon tayyorlik", "B2", "36", "(n.) eagerness, speed (For some reason, Chuck loved to help his mother whenever he could, so when his mother asked him to set the table he did so with alacrity.)"),
    ("alias", "taxallus, soxta ism", "B2", "36", "(n.) a false name or identity (He snuck past the guards by using an alias and fake ID.)"),
    ("allay", "bosmoq, tinchlantirmoq", "B2", "36", "(v.) to soothe, ease (The chairman of the Federal Reserve gave a speech to try to allay investors’ fears about an economic downturn.)"),
    ("aloof", "sovuqqon, o'zini olib qochuvchi", "B2", "36", "(adj.) reserved, distant (The scientist could sometimes seem aloof, as if he didn’t care about his friends or family, but really he was just thinking about quantum mechanics.)"),
    ("altercation", "janjal, aytishuv", "B2", "36", "(n.) a dispute, fight (Jason and Lionel blamed one another for the car accident, leading to an altercation.)"),
    ("allege", "da'vo qilmoq (isbotsiz)", "B2", "36", "(v.) to assert, usually without proof (The policeman had alleged that Marshall committed the crime, but after the investigation turned up no evidence, Marshall was set free.)"),
    ("amalgamate", "birlashtirmoq, qo'shmoq", "B2", "36", "(v.) to bring together, unite (Because of his great charisma, the presidential candidate was able to amalgamate all democrats and republicans under his banner.)"),
    ("ambivalent", "ikkilangan, qarama-qarshi hisli", "B2", "36", "(adj.) having opposing feelings (My feelings about Calvin are ambivalent because on one hand he is a loyal friend, but on the other, he is a cruel and vicious thief.)"),
    ("ameliorate", "yaxshilamoq", "B2", "36", "(v.) to improve (The tense situation was ameliorated when Sam proposed a solution everyone could agree upon.)"),
    ("amenable", "ko'nuvchan, gap qaytarmas", "B2", "36", "(adj.) willing, compliant (Our father was amenable when we asked him to drive us to the farm so we could go apple picking.)"),
    ("amenity", "qulaylik, shinamlik", "B2", "36", "(n.) an item that increases comfort (Bill Gates’s house is stocked with so many amenities, he never has to do anything for himself.)"),
    ("amicable", "do'stona, ahil", "B2", "36", "(adj.) friendly (Claudia and Jimmy got divorced, but amicably and without hard feelings.)"),
    ("amorous", "ishqiy, oshiqona", "B2", "36", "(adj.) showing love, particularly sexual (Whenever Albert saw Mariah wear her slinky red dress, he began to feel quite amorous.)"),
    ("amorphous", "shaklsiz, aniqmas", "B2", "36", "(adj.) without definite shape or type (The effort was doomed from the start, because the reasons behind it were so amorphous and hard to pin down.)"),
    ("anachronistic", "davriga mos kelmaydigan, eskirgan", "B2", "36", "(adj.) being out of correct chronological order (In this book you’re writing, you say that the Pyramids were built after the Titanic sank, which is anachronistic.)"),
    ("analgesic", "og'riq qoldiruvchi", "B2", "36", "(n.) something that reduces pain (Put this analgesic on the wound so that the poor man at least feels a little better.)"),
    ("analogous", "o'xshash, qiyoslanadigan", "B2", "36", "(adj.) similar to, so that an analogy can be drawn (Though they are unrelated genetically, the bone structure of whales and fish is quite analogous.)"),
    ("anarchist", "anarxist, hokimiyatsizlik tarafdori", "B2", "36", "(n.) one who wants to eliminate all government (An anarchist, Carmine wanted to dissolve every government everywhere.)"),
    ("anathema", "la'natlangan narsa, jirkanch narsa", "B2", "36", "(n.) a cursed, detested person (I never want to see that murderer. He is an anathema to me.)"),
    ("anecdote", "qiziq voqea, latifa", "B2", "36", "(n.) a short, humorous account (After dinner, Marlon told an anecdote about the time he got his nose stuck in a toaster.)"),
    ("anesthesia", "og'riqsizlantirish, narkoz", "B2", "36", "(n.) loss of sensation (When the nerves in his spine were damaged, Mr. Hollins suffered anesthesia in his legs.)"),
    # ---- Unit 37 (B2) ----
    ("anguish", "qattiq iztirob, azob", "B2", "37", "(n.) extreme sadness, torment (Angelos suffered terrible anguish when he learned that Buffy had died while combating a strange mystical force of evil.)"),
    ("animated", "jonli, g'ayratli", "B2", "37", "(adj.) lively (When he begins to talk about drama, which is his true passion, he becomes very animated.)"),
    ("annex", "qo'shib olmoq; qo'shimcha bino", "B2", "37", "1. (v.) to incorporate territory or space (After defeating them in battle, the Russians annexed Poland.) 2. (n.) a room attached to a larger room or space (He likes to do his studying in a little annex attached to the main reading room in the library.)"),
    ("annul", "bekor qilmoq (nikoh, qaror)", "B2", "37", "(v.) to make void or invalid (After seeing its unforeseen and catastrophic effects, Congress sought to annul the law.)"),
    ("anomaly", "g'ayrioddiy holat, istisno", "B2", "37", "(n.) something that does not fit into the normal order (“That rip in the spacetime continuum is certainly a spatial anomaly,” said Spock to Captain Kirk.)"),
    ("anonymous", "nomsiz, imzosiz", "B2", "37", "(adj.) being unknown, unrecognized (Mary received a love poem from an anonymous admirer.)"),
    ("antagonism", "dushmanlik, ziddiyat", "B2", "37", "(n.) hostility (Superman and Bizarro Superman shared a mutual antagonism, and often fought.)"),
    ("antecedent", "oldingi narsa, ajdod", "B2", "37", "(n.) something that came before (The great tradition of Western culture had its antecedent in the culture of Ancient Greece.)"),
    ("anthology", "to'plam, antologiya", "B2", "37", "(n.) a selected collection of writings, songs, etc. (The new anthology of Bob Dylan songs contains all his greatest hits and a few songs that you might never have heard before.)"),
    ("antipathy", "yoqtirmaslik, nafrat", "B2", "37", "(n.) a strong dislike, repugnance (I know you love me, but because you are a liar and a thief, I feel nothing but antipathy for you.)"),
    ("antiquated", "eskirgan, qadimiy", "B2", "37", "(adj.) old, out of date (That antiquated car has none of the features, like power windows and steering, that make modern cars so great.)"),
    ("antiseptic", "mikrobga qarshi, antiseptik", "B2", "37", "(adj.) clean, sterile (The antiseptic hospital was very bare, but its cleanliness helped to keep patients healthy.)"),
    ("antediluvian", "juda qadimgi, to'fon davridan qolgan", "B2", "37", "(adj.) ancient (The antediluvian man still believed that Eisenhower was president of the United States and that hot dogs cost a nickel.)"),
    ("antithesis", "mutlaq zid, qarama-qarshilik", "B2", "37", "(n.) the absolute opposite (Your values, which hold war and violence in the highest esteem, are the antithesis of my pacifist beliefs.)"),
    ("anxiety", "xavotir, bezovtalik", "B2", "37", "(n.) intense uneasiness (When he heard about the car crash, he felt anxiety because he knew that his girlfriend had been driving on the road where the accident occurred.)"),
    ("apathetic", "befarq, loqayd", "B2", "37", "(adj.) lacking concern, emotion (Uninterested in politics, Bruno was apathetic about whether he lived under a capitalist or communist regime.)"),
    ("apocryphal", "shubhali, to'qima (haqiqati isbotlanmagan)", "B2", "37", "(adj.) fictitious, false, wrong (Because I am standing before you, it seems obvious that the stories circulating about my demise were apocryphal.)"),
    ("appease", "tinchlantirmoq, ko'nglini olmoq", "B2", "37", "(v.) to calm, satisfy (When the child cries, the mother gives him candy to appease him.)"),
    ("appraise", "baholamoq, narxlamoq", "B2", "37", "(v.) to assess the worth or value of (A realtor will come over tonight to appraise our house.)"),
    ("apprehend", "tushunmoq; qo'lga olmoq", "B2", "37", "1. (v.) to seize, arrest (The criminal was apprehended at the scene.) 2. (v.) to perceive, understand, grasp (The student has trouble apprehending concepts in math and science.)"),
    ("approbation", "ma'qullash, olqish", "B2", "37", "(n.) praise (The crowd welcomed the heroes with approbation.)"),
    ("aquatic", "suvga oid, suvda yashovchi", "B2", "37", "(adj.) relating to water (The marine biologist studies starfish and other aquatic creatures.)"),
    ("arable", "ekinbop, haydaladigan (yer)", "B2", "37", "(adj.) suitable for growing crops (The farmer purchased a plot of arable land on which he will grow corn and sprouts.)"),
    ("arbiter", "hakam, hal qiluvchi shaxs", "B2", "37", "(n.) one who can resolve a dispute, make a decision (The divorce court judge will serve as the arbiter between the estranged husband and wife.)"),
    ("arbitrary", "o'zboshimcha, asossiz", "B2", "37", "(adj.) based on factors that appear random (The boy’s decision to choose one college over another seems arbitrary.)"),
    ("arbitration", "hakamlik muhokamasi", "B2", "37", "(n.) the process or act of resolving a dispute (The employee sought official arbitration when he could not resolve a disagreement with his supervisor.)"),
    ("arboreal", "daraxtga oid, daraxtda yashovchi", "B2", "37", "(adj.) of or relating to trees (Leaves, roots, and bark are a few arboreal traits.)"),
    ("arcane", "sirli, faqat xoslarga ma'lum", "B2", "37", "(adj.) obscure, secret, known only by a few (The professor is an expert in arcane Lithuanian literature.)"),
    ("archaic", "eskirgan, qadimiy", "B2", "37", "(adj.) of or relating to an earlier period in time, outdated (In a few select regions of Western Mongolian, an archaic Chinese dialect is still spoken.)"),
    ("archetypal", "asl namunaviy, timsoliy", "B2", "37", "(adj.) the most representative or typical example of something (Some believe George Washington, with his flowing white hair and commanding stature, was the archetypal politician.)"),
    ("ardor", "otash, ehtiros", "B2", "37", "(n.) extreme vigor, energy, enthusiasm (The soldiers conveyed their ardor with impassioned battle cries.)"),
    ("arid", "qurg'oqchil, qaqroq", "B2", "37", "(adj.) excessively dry (Little other than palm trees and cacti grow successfully in arid environments.)"),
    ("arrogate", "o'zboshimchalik bilan da'vo qilmoq", "B2", "37", "(v.) to take without justification (The king arrogated the right to order executions to himself exclusively.)"),
    ("artifact", "qadimiy buyum, yodgorlik", "B2", "37", "(n.) a remaining piece from an extinct culture or place (The scientists spent all day searching the cave for artifacts from the ancient Mayan civilization.)"),
    ("artisan", "hunarmand", "B2", "37", "(n.) a craftsman (The artisan uses wood to make walking sticks.)"),
    ("ascetic", "tarkidunyo, zohid", "B2", "37", "(adj.) practicing restraint as a means of self-discipline, usually religious (The priest lives an ascetic life devoid of television, savory foods, and other pleasures.)"),
    ("ascribe", "nisbat bermoq, bog'lamoq", "B2", "37", "(v.) to assign, credit, attribute to (Some ascribe the invention of fireworks and dynamite to the Chinese.)"),
    # ---- Unit 38 (B2) ----
    ("aspire", "intilmoq, orzu qilmoq", "B2", "38", "(v.) to long for, aim toward (The young poet aspires to publish a book of verse someday.)"),
    ("assail", "hujum qilmoq, tashlanmoq", "B2", "38", "(v.) to attack (At dawn, the war planes assailed the boats in the harbor.)"),
    ("assiduous", "tirishqoq, mehnatkash", "B2", "38", "(adj.) hard-working, diligent (The construction workers erected the skyscraper during two years of assiduous labor.)"),
    ("assuage", "yumshatmoq, bosmoq", "B2", "38", "(v.) to ease, pacify (The mother held the baby to assuage its fears.)"),
    ("aspersion", "tuhmat, bo'hton", "B2", "38", "(n.) a curse, expression of ill-will (The rival politicians repeatedly cast aspersions on each others’ integrity.)"),
    ("astute", "ziyrak, uddaburon", "B2", "38", "(adj.) very clever, crafty (Much of Roger’s success in politics results from his ability to provide astute answers to reporters’ questions.)"),
    ("asylum", "boshpana, panoh", "B2", "38", "1. (n.) a place of refuge, protection, a sanctuary (For Thoreau, the forest served as an asylum from the pressures of urban life.) 2. (n.) an institution in which the insane are kept (Once diagnosed by a certified psychiatrist, the man was put in an asylum.)"),
    ("atone", "gunohini yuvmoq, tovon to'lamoq", "B2", "38", "(v.) to repent, make amends (The man atoned for forgetting his wife’s birthday by buying her five dozen roses.)"),
    ("atrophy", "so'lish, zaiflashish", "B2", "38", "(v.) to wither away, decay (If muscles do not receive enough blood, they will soon atrophy and die.)"),
    ("attain", "erishmoq", "B2", "38", "(v.) to achieve, arrive at (The athletes strived to attain their best times in competition.)"),
    ("attribute", "xususiyat; nisbat bermoq", "B2", "38", "1. (v.) to credit, assign (He attributes all of his success to his mother’s undying encouragement.) 2. (n.) a facet or trait (Among the beetle’s most peculiar attributes is its thorny protruding eyes.)"),
    ("atypical", "g'ayrioddiy, odatdan tashqari", "B2", "38", "(adj.) not typical, unusual (Screaming and crying is atypical adult behavior.)"),
    ("audacious", "jasur, betgachopar", "B2", "38", "(adj.) excessively bold (The security guard was shocked by the fan’s audacious attempt to offer him a bribe.)"),
    ("audible", "eshitiladigan", "B2", "38", "(adj.) able to be heard (The missing person’s shouts were unfortunately not audible.)"),
    ("augment", "ko'paytirmoq, kuchaytirmoq", "B2", "38", "(v.) to add to, expand (The eager student seeks to augment his knowledge of French vocabulary by reading French literature.)"),
    ("auspicious", "xayrli, omadli", "B2", "38", "(adj.) favorable, indicative of good things (The tennis player considered the sunny forecast an auspicious sign that she would win her match.)"),
    ("austere", "qattiqqo'l, hashamsiz", "B2", "38", "(adj.) very bare, bleak (The austere furniture inside the abandoned house made the place feel haunted.)"),
    ("avarice", "ochko'zlik, xasislik", "B2", "38", "(n.) excessive greed (The banker’s avarice led him to amass a tremendous personal fortune.)"),
    ("avenge", "qasos olmoq, o'chini olmoq", "B2", "38", "(v.) to seek revenge (The victims will take justice into their own hands and strive to avenge themselves against the men who robbed them.)"),
    ("aversion", "yoqtirmaslik, jirkanish", "B2", "38", "(n.) a particular dislike for something (Because he’s from Hawaii, Ben has an aversion to autumn, winter, and cold climates in general.)"),
    ("balk", "tixirlik qilmoq, bosh tortmoq", "B2", "38", "(v.) to stop, block abruptly (Edna’s boss balked at her request for another raise.)"),
    ("ballad", "ballada, xalq qo'shig'i", "B2", "38", "(n.) a love song (Greta’s boyfriend played her a ballad on the guitar during their walk through the dark woods.)"),
    ("banal", "siyqasi chiqqan, oddiy", "B2", "38", "(adj.) dull, commonplace (The client rejected our proposal because they found our presentation banal and unimpressive.)"),
    ("bane", "baloi azim, ofat", "B2", "38", "(n.) a burden (Advanced physics is the bane of many students’ academic lives.)"),
    ("bard", "shoir, baxshi", "B2", "38", "(n.) a poet, often a singer as well (Shakespeare is often considered the greatest bard in the history of the English language.)"),
    ("bashful", "uyatchan, tortinchoq", "B2", "38", "(adj.) shy, excessively timid (Frankie’s mother told him not to be bashful when he refused to attend the birthday party.) battery 1.(n.) a device that supplies power (Most cars run on a combination of power from a battery and gasoline.) 2. (n.)assault, beating (Her husband was accused of assault and battery after he attacked a man on the sidewalk.)"),
    ("beguile", "aldab rom qilmoq, maftun etmoq", "B2", "38", "(v.) to trick, deceive (The thief beguiled his partners into surrendering all of their money to him.)"),
    ("behemoth", "bahaybat maxluq, gigant", "B2", "38", "(n.) something of tremendous power or size (The new aircraft carrier is among several behemoths that the Air Force has added to its fleet.)"),
    ("benevolent", "xayrixoh, saxovatli", "B2", "38", "(adj.) marked by goodness or doing good (Police officers should be commended for their benevolent service to the community.)"),
    ("bequeath", "meros qoldirmoq", "B2", "38", "(v.) to pass on, give (Jon’s father bequeathed his entire estate to his mother.)"),
    ("berate", "qattiq koyimoq", "B2", "38", "(v.) to scold vehemently (The angry boss berated his employees for failing to meet their deadline.)"),
    ("bereft", "mahrum, judo bo'lgan", "B2", "38", "(adj.) devoid of, without (His family was bereft of food and shelter following the tornado.)"),
    ("beseech", "yolvormoq, iltijo qilmoq", "B2", "38", "(v.) to beg, plead, implore (The servant beseeched the king for food to feed his starving family.)"),
    ("benign", "beozor, xavfsiz", "B2", "38", "(adj.) favorable, not threatening, mild (We were all relieved to hear that the medical tests determined her tumor to be benign.)"),
    ("bilk", "aldab pulini olmoq, shilmoq", "B2", "38", "(v.) cheat, defraud (The lawyer discovered that this firm had bilked several clients out of thousands of dollars.)"),
    ("blandish", "xushomad bilan ko'ndirmoq", "B2", "38", "(v.) to coax by using flattery (Rachel’s assistant tried to blandish her into accepting the deal.)"),
    ("blemish", "dog', nuqson", "B2", "38", "(n.) an imperfection, flaw (The dealer agreed to lower the price because of the many blemishes on the surface of the wooden furniture.)"),
    ("blight", "ofat, kasof; nobud qilmoq", "B2", "38", "1. (n.) a plague, disease (The potato blight destroyed the harvest and bankrupted many families.) 2. (n.) something that destroys hope (His bad morale is a blight upon this entire operation.)"),
    # ---- Unit 39 (B2) ----
    ("bombastic", "balandparvoz, dabdabali (gap)", "B2", "39", "(adj.) excessively confident, pompous (The singer’s bombastic performance disgusted the crowd.)"),
    ("boon", "ne'mat, katta foyda", "B2", "39", "(n.) a gift or blessing (The good weather has been a boon for many businesses located near the beach.)"),
    ("bourgeois", "burjua, o'rta hol mulkdor", "B2", "39", "(n.) a middle-class person, capitalist (Many businessmen receive criticism for their bourgeois approach to life.)"),
    ("brazen", "surbet, uyatsiz", "B2", "39", "(adj.) excessively bold, brash (Critics condemned the novelist’s brazen attempt to plagiarize Hemingway’s story.)"),
    ("brusque", "qo'pol, keskin (muomala)", "B2", "39", "(adj.) short, abrupt, dismissive (The captain’s brusque manner offended the passengers.)"),
    ("buffet", "urmoq, do'pposlamoq; bufet", "B2", "39", "1. (v.) to strike with force (The strong winds buffeted the ships, threatening to capsize them.) 2. (n.) an arrangement of food set out on a table (Rather than sitting around a table, the guests took food from our buffet and ate standing up.)"),
    ("burnish", "yaltiratmoq, sayqallamoq", "B2", "39", "(v.) to polish, shine (His mother asked him to burnish the silverware before setting the table.)"),
    ("buttress", "tirgak; quvvatlamoq", "B2", "39", "1. (v.) to support, hold up (The column buttresses the roof above the statue.) 2. (n.) something that offers support (The buttress supports the roof above the statues.)"),
    ("cacophony", "quloqni teshuvchi shovqin, g'ala-g'ovur", "B2", "39", "(n.) tremendous noise, disharmonious sound (The elementary school orchestra created a cacophony at the recital.)"),
    ("cadence", "ohang, ritm", "B2", "39", "(n.) a rhythm, progression of sound (The pianist used the foot pedal to emphasize the cadence of the sonata.)"),
    ("cajole", "yalinib-yolvorib ko'ndirmoq", "B2", "39", "(v.) to urge, coax (Fred’s buddies cajoled him into attending the bachelor party.)"),
    ("calamity", "falokat, ofat", "B2", "39", "(n.) an event with disastrous consequences (The earthquake in San Francisco was a calamity worse than any other natural disaster in history.)"),
    ("calibrate", "sozlamoq, o'lchovini to'g'rilamoq", "B2", "39", "(v.) to set, standardize (The mechanic calibrated the car’s transmission to make the motor run most efficiently.)"),
    ("callous", "toshbag'ir, befarq", "B2", "39", "(adj.) harsh, cold, unfeeling (The murderer’s callous lack of remorse shocked the jury.)"),
    ("calumny", "tuhmat, bo'hton", "B2", "39", "(n.) an attempt to spoil someone else’s reputation by spreading lies (The local official’s calumny ended up ruining his opponent’s prospect of winning the election.)"),
    ("camaraderie", "o'rtoqlik ruhi, jo'ralik", "B2", "39", "(n.) brotherhood, jovial unity (Camaraderie among employees usually leads to success in business.)"),
    ("candor", "ochiqko'ngillik, samimiylik", "B2", "39", "(n.) honesty, frankness (We were surprised by the candor of the mayor’s speech because he is usually rather evasive.)"),
    ("canny", "hushyor, pixini yorgan", "B2", "39", "(adj.) shrewd, careful (The canny runner hung at the back of the pack through much of the race to watch the other runners, and then sprinted past them at the end.)"),
    ("canvas", "bo'yoq matosi, kanva", "B2", "39", "1. (n.) a piece of cloth on which an artist paints (Picasso liked to work on canvas rather than on bare cement.) 2. (v.) to cover, inspect (We canvassed the neighborhood looking for clues.)"),
    ("capacious", "keng, sig'imli", "B2", "39", "(adj.) very spacious (The workers delighted in their new capacious office space.)"),
    ("capricious", "injiq, o'zgaruvchan", "B2", "39", "(adj.) subject to whim, fickle (The young girl’s capricious tendencies made it difficult for her to focus on achieving her goals.)"),
    ("captivate", "maftun etmoq, rom qilmoq", "B2", "39", "(v.) to get the attention of, hold (The fireworks captivated the young boy, who had never seen such things before.)"),
    ("carouse", "aysh-ishrat qilmoq, bazm qurmoq", "B2", "39", "(v.) to party, celebrate (We caroused all night after getting married.)"),
    ("carp", "mayda-chuydaga ilinmoq, g'ijinib tanqid qilmoq", "B2", "39", "(v.) to annoy, pester (The husband divorced his wife after listening to her carping voice for decades.)"),
    ("capitulate", "taslim bo'lmoq", "B2", "39", "(v.) to surrender (The army finally capitulated after fighting a long costly battle.)"),
    ("catalog", "ro'yxatga olmoq; katalog", "B2", "39", "1. (v.) to list, enter into a list (The judge cataloged the victim’s injuries before calculating how much money he would award.) 2. (n.) a list or collection (We received a catalog from J. Crew that displayed all of their new items.)"),
    ("catalyze", "tezlashtirmoq, turtki bermoq", "B2", "39", "(v.) to charge, inspire (The president’s speech catalyzed the nation and resuscitated the economy.)"),
    ("caucus", "partiya yig'ini, kengash", "B2", "39", "(n.) a meeting usually held by people working toward the same goal (The ironworkers held a caucus to determine how much of a pay increase they would request.)"),
    ("caustic", "achchiq, kuydiruvchi (gap)", "B2", "39", "(adj.) bitter, biting, acidic (The politicians exchanged caustic insults for over an hour during the debate.)"),
    ("cavort", "sakrab o'ynamoq, shataloq otmoq", "B2", "39", "(v.) to leap about, behave boisterously (The adults ate their dinners on the patio, while the children cavorted around the pool.)"),
    ("censure", "qoralamoq, tanbeh bermoq", "B2", "39", "1. (n.) harsh criticism (The frustrated teenager could not put up with anymore of her critical mother’s censure.) 2. (v.) to rebuke formally (The principal censured the head of the English Department for forcing students to learn esoteric vocabulary.)"),
    ("cerebral", "aqliy, miyaga oid", "B2", "39", "(adj.) related to the intellect (The books we read in this class are too cerebral— they don’t engage my emotions at all.)"),
    ("chaos", "tartibsizlik, to'polon", "B2", "39", "(n.) absolute disorder (Mr. Thornton’s sudden departure for the lavatory plunged his classroom into chaos.)"),
    ("chastise", "jazolamoq, qattiq koyimoq", "B2", "39", "(v.) to criticize severely (After being chastised by her peers for mimicking Britney Spears, Miranda dyed her hair black and affected a Gothic style.)"),
    ("chide", "koyimoq, tanbeh bermoq", "B2", "39", "(v.) to voice disapproval (Lucy chided Russell for his vulgar habits and sloppy appearance.)"),
    ("choreography", "raqs sanʼati, xoreografiya", "B2", "39", "(n.) the arrangement of dances (The plot of the musical was banal, but the choreography was stunning.)"),
    ("chronicle", "yilnoma, solnoma", "B2", "39", "1. (n.) a written history (The library featured the newly updated chronicle of World War II.) 2. (v.) to write a history (Albert’s diary chronicled the day-to-day growth of his obsession with Cynthia.)"),
    ("chronological", "vaqt tartibidagi, xronologik", "B2", "39", "(adj.) arranged in order of time (Lionel carefully arranged the snapshots of his former girlfriends in chronological order, and then set fire to them.)"),
    # ---- Unit 40 (B2) ----
    ("circuitous", "aylanma, egri-bugri", "B2", "40", "(adj.) roundabout (The bus’s circuitous route took us through numerous outlying suburbs.)"),
    ("circumlocution", "aylantirib gapirish, gapni cho'zish", "B2", "40", "(n.) indirect and wordy language (The professor’s habit of speaking in circumlocutions made it difficult to follow his lectures.)"),
    ("circumscribed", "chegaralangan, cheklangan", "B2", "40", "(adj.) marked off, bounded (The children were permitted to play tag only within a carefully circumscribed area of the lawn.)"),
    ("circumspect", "ehtiyotkor, mulohazali", "B2", "40", "(adj.) cautious (Though I promised Rachel’s father I would bring her home promptly by midnight, it would have been more circumspect not to have specified a time.)"),
    ("circumvent", "chetlab o'tmoq, aylanib o'tmoq", "B2", "40", "(v.) to get around (The school’s dress code forbidding navel-baring jeans was circumvented by the determined students, who were careful to cover up with long coats when administrators were nearby.)"),
    ("clairvoyant", "g'aybni ko'ruvchi, karomatgo'y", "B2", "40", "(adj.) able to perceive things that normal people cannot (Zelda’s uncanny ability to detect my lies was nothing short of clairvoyant.)"),
    ("clamor", "shovqin-suron, dod-faryod", "B2", "40", "1. (n.) loud noise (Each morning the birds outside my window make such a clamor that they wake me up.) 2. (v.)to loudly insist (Neville’s fans clamored for him to appear on stage, but he had passed out on the floor of his dressing room.)"),
    ("clandestine", "yashirin, maxfiy", "B2", "40", "(adj.) secret (Announcing to her boyfriend that she was going to the gym, Sophie actually went to meet Joseph for a clandestine liaison.)"),
    ("cleave", "yorib bo'lmoq; yopishmoq", "B2", "40", "1. (v.) to divide into parts (Following the scandalous disgrace of their leader, the entire political party cleaved into warring factions.) 2. (v.) to stick together firmly (After resolving their marital problems, Junior and Rosa cleaved to one another all the more tightly.)"),
    ("clergy", "ruhoniylar", "B2", "40", "(n.) members of Christian holy orders (Though the villagers viewed the church rectory as quaint and charming, the clergy who lived there regarded it as a mildewy and dusty place that aggravated their allergies.)"),
    ("cloying", "me'daga tegadigan darajada shirin", "B2", "40", "(adj.) sickeningly sweet (Though Ronald was physically attractive, Maud found his constant compliments and solicitous remarks cloying.)"),
    ("coagulate", "quyuqlashmoq, ivimoq", "B2", "40", "(v.) to thicken, clot (The top layer of the pudding had coagulated into a thick skin.)"),
    ("clemency", "shafqat, muruvvat", "B2", "40", "(n.) mercy (After he forgot their anniversary, Martin could only beg Maria for clemency.)"),
    ("coalesce", "qo'shilib birlashmoq", "B2", "40", "(v.) to fuse into a whole (Gordon’s ensemble of thrift-shop garments coalesced into a surprisingly handsome outfit.)"),
    ("cobbler", "etikdo'z", "B2", "40", "(n.) a person who makes or repairs shoes (I had my neighborhood cobbler replace my worn-out leather soles with new ones.)"),
    ("coerce", "majburlamoq, zo'rlamoq", "B2", "40", "(v.) to make somebody do something by force or threat (The court decided that Vanilla Ice did not have to honor the contract because he had been coerced into signing it.)"),
    ("cogent", "ishonarli, asosli", "B2", "40", "(adj.) intellectually convincing (Irene’s arguments in favor of abstinence were so cogent that I could not resist them.)"),
    ("cognizant", "xabardor, anglagan", "B2", "40", "(adj.) aware, mindful (Jake avoided speaking to women in bars because he was cognizant of the fact that drinking impairs his judgment.)"),
    ("collateral", "garov; yondosh", "B2", "40", "1. (adj.) secondary (Divorcing my wife had the collateral effect of making me poor, as she was the only one of us with a job or money.) 2. (n.) security for a debt (Jacob left his watch as collateral for the $500 loan.)"),
    ("colloquial", "og'zaki nutqqa xos, so'zlashuv", "B2", "40", "(adj.) characteristic of informal conversation (Adam’s essay on sexual response in primates was marked down because it contained too many colloquial expressions.)"),
    ("collusion", "til biriktirish, fitna", "B2", "40", "(n.) secret agreement, conspiracy (The three law students worked in collusion to steal the final exam.)"),
    ("colossus", "ulkan haykal, gigant", "B2", "40", "(n.) a gigantic statue or thing (For 56 years, the ancient city of Rhodes featured a colossus standing astride its harbor.)"),
    ("combustion", "yonish", "B2", "40", "(n.) the act or process of burning (The unexpected combustion of the prosecution’s evidence forced the judge to dismiss the case against Ramirez.)"),
    ("commendation", "maqtov, taqdirnoma", "B2", "40", "(n.) a notice of approval or recognition (Jared received a commendation from Linda, his supervisor, for his stellar performance.)"),
    ("commensurate", "mutanosib, teng", "B2", "40", "(adj.) corresponding in size or amount (Ahab selected a very long roll and proceeded to prepare a tuna salad sandwich commensurate with his enormous appetite.)"),
    ("commodious", "keng, qulay", "B2", "40", "(adj.) roomy (Holden invited the three women to join him in the back seat of the taxicab, assuring them that the car was quite commodious.)"),
    ("compelling", "ishontiruvchi, o'ziga tortuvchi", "B2", "40", "(adj.) forceful, demanding attention (Eliot’s speech was so compelling that Lenore accepted his proposal on the spot.)"),
    ("complacency", "o'zidan mamnunlik, beparvolik", "B2", "40", "(n.) self-satisfied ignorance of danger (Colin tried to shock his friends out of their complacency by painting a frightening picture of what might happen to them.)"),
    ("complement", "to'ldirmoq; to'ldiruvchi", "B2", "40", "(v.) to complete, make perfect (Ann’s scarf complements her blouse beautifully, making her seem fully dressed even though she isn’t wearing a coat.)"),
    ("compliant", "itoatkor, ko'nuvchan", "B2", "40", "(adj.) ready to adapt oneself to another’s wishes (Sue had very strong opinions about what to do on a first date, and Ted was absolutely compliant.)"),
    ("complicit", "jinoyatga sherik, aloqador", "B2", "40", "(adj.) being an accomplice in a wrongful act (By keeping her daughter’s affair a secret, Maddie became complicit in it.)"),
    ("compliment", "maqtov, iltifot", "B2", "40", "(n.) an expression of esteem or approval (I blushed crimson when Emma gave me a compliment on my new haircut.)"),
    ("compound", "murakkablashtirmoq; birikma", "B2", "40", "1. (v.) to combine parts (The difficulty of finding a fire escape amid the smoke was compounded with the dangers posed by the panicking crowds.) 2. (n.) a combination of different parts (My attraction to Donna was a compound of curiosity about the unknown, physical desire, and intellectual admiration.) 3. (n.) a walled area containing a group of buildings (When the fighting started, Joseph rushed into the family compound because it was safe and well defended.)"),
    ("compress", "siqmoq, zichlamoq", "B2", "40", "(v.) to apply pressure, squeeze together (Lynn compressed her lips into a frown.)"),
    ("compunction", "vijdon azobi, pushaymon", "B2", "40", "(n.) distress caused by feeling guilty (He felt compunction for the shabby way he’d treated her.)"),
    ("concede", "tan olmoq, yon bermoq", "B2", "40", "(v.) to accept as valid (Andrew had to concede that what his mother said about Diana made sense.)"),
    ("conciliatory", "yarashtiruvchi, murosachi", "B2", "40", "(adj.) friendly, agreeable (I took Amanda’s invitation to dinner as a very conciliatory gesture.)"),
    # ---- Unit 41 (B2) ----
    ("concise", "qisqa va lo'nda", "B2", "41", "(adj.) brief and direct in expression (Gordon did not like to waste time, and his instructions to Brenda were nothing if not concise.)"),
    ("concoct", "to'qib chiqarmoq, qorishtirib tayyorlamoq", "B2", "41", "(v.) to fabricate, make up (She concocted the most ridiculous story to explain her absence.)"),
    ("concomitant", "hamroh bo'luvchi, yondosh", "B2", "41", "(adj.) accompanying in a subordinate fashion (His dislike of hard work carried with it a concomitant lack of funds.)"),
    ("concord", "totuvlik, hamjihatlik", "B2", "41", "(n.) harmonious agreement (Julie and Harold began the evening with a disagreement, but ended it in a state of perfect concord.)"),
    ("condolence", "ta'ziya, hamdardlik", "B2", "41", "(n.) an expression of sympathy in sorrow (Brian lamely offered his condolences on the loss of his sister’s roommate’s cat.)"),
    ("condone", "ko'z yummoq, kechirmoq", "B2", "41", "(v.) to pardon, deliberately overlook (He refused to condone his brother’s crime.)"),
    ("conduit", "quvur, o'tkazgich yo'l", "B2", "41", "(n.) a pipe or channel through which something passes (The water flowed through the conduit into the container.)"),
    ("confection", "shirinlik, qandolat", "B2", "41", "(n.) a sweet, fancy food (We went to the mall food court and purchased a delicious confection.)"),
    ("confidant", "sirdosh do'st", "B2", "41", "(n.) a person entrusted with secrets (Shortly after we met, she became my chief confidant.)"),
    ("conflagration", "katta yong'in", "B2", "41", "(n.) great fire (The conflagration consumed the entire building.)"),
    ("confluence", "qo'shilish joyi (daryolar), uyg'unlashuv", "B2", "41", "(n.) a gathering together (A confluence of different factors made tonight the perfect night.)"),
    ("conformist", "urf-odatga ergashuvchi, konformist", "B2", "41", "(n.) one who behaves the same as others (Julian was such a conformist that he had to wait and see if his friends would do something before he would commit.)"),
    ("confound", "boshini qotirmoq, chalkashtirmoq", "B2", "41", "(v.) to frustrate, confuse (MacGuyver confounded the policemen pursuing him by covering his tracks.)"),
    ("congeal", "qotmoq, quyuqlashmoq", "B2", "41", "(v.) to thicken into a solid (The sauce had congealed into a thick paste.)"),
    ("congenial", "hamfikr, yoqimli", "B2", "41", "(adj.) pleasantly agreeable (His congenial manner made him popular wherever he went.)"),
    ("congregation", "jamoa, yig'ilganlar (ibodatda)", "B2", "41", "(n.) a gathering of people, especially for religious services (The priest told the congregation that he would be retiring.)"),
    ("congruity", "muvofiqlik, uyg'unlik", "B2", "41", "(n.) the quality of being in agreement (Bill and Veronica achieved a perfect congruity of opinion.)"),
    ("connive", "til biriktirmoq, fitna qilmoq", "B2", "41", "(v.) to plot, scheme (She connived to get me to give up my vacation plans.)"),
    ("consecrate", "muqaddas deb e'lon qilmoq, bag'ishlamoq", "B2", "41", "(v.) to dedicate something to a holy purpose (Arvin consecrated his spare bedroom as a shrine to Christina.)"),
    ("consensus", "umumiy kelishuv, yakdillik", "B2", "41", "(n.) an agreement of opinion (The jury was able to reach a consensus only after days of deliberation.)"),
    ("consign", "topshirmoq, jo'natmoq", "B2", "41", "(v.) to give something over to another’s care (Unwillingly, he consigned his mother to a nursing home.)"),
    ("consolation", "tasalli, yupanch", "B2", "41", "(n.) an act of comforting (Darren found Alexandra’s presence to be a consolation for his suffering.)"),
    ("consonant", "uyg'un, hamohang", "B2", "41", "(adj.) in harmony (The singers’ consonant voices were beautiful.)"),
    ("constituent", "saylovchi; tarkibiy qism", "B2", "41", "(n.) an essential part (The most important constituent of her perfume is something called ambergris.)"),
    ("construe", "talqin qilmoq, tushunmoq", "B2", "41", "(v.) to interpret (He construed her throwing his clothes out the window as a signal that she wanted him to leave.)"),
    ("consummate", "yakuniga yetkazmoq; barkamol", "B2", "41", "(v.) to complete a deal; to complete a marriage ceremony through sexual intercourse (Erica and Donald consummated their agreement in the executive boardroom.)"),
    ("contentious", "janjalkash, bahsli", "B2", "41", "(adj.) having a tendency to quarrel or dispute (George’s contentious personality made him unpopular with his classmates.)"),
    ("contravene", "zid bormoq, buzmoq (qoidani)", "B2", "41", "(v.) to contradict, oppose, violate (Edwidge contravened his landlady’s rule against overnight guests.)"),
    ("contrite", "chin dildan pushaymon", "B2", "41", "(adj.) penitent, eager to be forgiven (Blake’s contrite behavior made it impossible to stay angry at him.)"),
    ("contusion", "lat yeyish, momataloq", "B2", "41", "(n.) bruise, injury (The contusions on his face suggested he’d been in a fight.)"),
    ("contemporaneous", "bir davrda yuz bergan, zamondosh", "B2", "41", "(adj.) existing during the same time (Though her novels do not feature the themes of Romanticism, Jane Austen’s work was contemporaneous with that of Wordsworth and Byron.)"),
    ("conundrum", "boshqotirma, jumboq", "B2", "41", "(n.) puzzle, problem (Interpreting Jane’s behavior was a constant conundrum.)"),
    ("convene", "yig'ilmoq, chaqirmoq (majlis)", "B2", "41", "(v.) to call together (Jason convened his entire extended family for a discussion.)"),
    ("convention", "urf-odat; qurultoy", "B2", "41", "1. (n.) an assembly of people (The hotel was full because of the cattleranchers’ convention.) 2. (n.) a rule, custom (The cattle-ranchers have a convention that you take off your boots before entering their houses.)"),
    ("convivial", "quvnoq, davraboz", "B2", "41", "(adj.) characterized by feasting, drinking, merriment (The restaurant’s convivial atmosphere put me immediately at ease.)"),
    ("convoluted", "o'ta chalkash, murakkab", "B2", "41", "(adj.) intricate, complicated (Grace’s story was so convoluted that I couldn’t follow it.)"),
    ("copious", "mo'l-ko'l, serob", "B2", "41", "(adj.) profuse, abundant (Copious amounts of Snapple were imbibed in the cafeteria.)"),
    ("cordial", "samimiy, iliq (muomala)", "B2", "41", "(adj.) warm, affectionate (His cordial greeting melted my anger at once.)"),
    # ---- Unit 42 (B2) ----
    ("coronation", "toj kiydirish marosimi", "B2", "42", "(n.) the act of crowning (The new king’s coronation occurred the day after his father’s death.)"),
    ("corpulence", "semizlik, to'lalik", "B2", "42", "(adj.)extreme fatness (Henry’s corpulence did not make him any less attractive to his charming, svelte wife.)"),
    ("corroborate", "tasdiqlamoq, dalil bilan quvvatlamoq", "B2", "42", "(v.) to support with evidence (Luke’s seemingly outrageous claim was corroborated by witnesses.)"),
    ("corrosive", "yemiruvchi, zanglatuvchi", "B2", "42", "(adj.) having the tendency to erode or eat away (The effect of the chemical was highly corrosive.)"),
    ("counteract", "qarshi ta'sir ko'rsatmoq", "B2", "42", "(v.) to neutralize, make ineffective (The antidote counteracted the effect of the poison.)"),
    ("coup", "davlat to'ntarishi; zo'r yutuq", "B2", "42", "1. (n.) a brilliant, unexpected act (Alexander pulled off an amazing coup when he got a date with Cynthia by purposely getting hit by her car.) 2. (n.) the overthrow of a government and assumption of authority (In their coup attempt, the army officers stormed the Parliament and took all the legislators hostage.)"),
    ("covet", "ko'z olaytirmoq, havas bilan istamoq", "B2", "42", "(v.) to desire enviously (I coveted Moses’s house, wife, and car.)"),
    ("covert", "yashirin, pinhoniy", "B2", "42", "(adj.) secretly engaged in (Nerwin waged a covert campaign against his enemies, while outwardly appearing to remain friendly.)"),
    ("credulity", "soddadillik, laqmalik", "B2", "42", "(n.) readiness to believe (His credulity made him an easy target for con men.)"),
    ("crescendo", "avjiga chiqish, kuchayish", "B2", "42", "(n.) a steady increase in intensity or volume (The crescendo of the brass instruments gave the piece a patriotic feel.)"),
    ("criteria", "mezonlar, o'lchovlar", "B2", "42", "(n.) standards by which something is judged (Among Mrs. Fields’s criteria for good cookies are that they be moist and chewy.)"),
    ("culmination", "cho'qqi, avj nuqtasi", "B2", "42", "(n.) the climax toward which something progresses (The culmination of the couple’s argument was the decision to divorce.)"),
    ("culpable", "aybdor, javobgar", "B2", "42", "(adj.) deserving blame (He was culpable of the crime, and was sentenced to perform community service for 75 years.)"),
    ("cultivate", "yetishtirmoq, rivojlantirmoq", "B2", "42", "(v.) to nurture, improve, refine (At the library, she cultivated her interest in spy novels.)"),
    ("cunning", "ayyor, hiylakor", "B2", "42", "(adj.) sly, clever at being deceitful (The general devised a cunning plan to surprise the enemy.)"),
    ("cupidity", "ochko'zlik, molparastlik", "B2", "42", "(n.) greed, strong desire (His cupidity made him enter the abandoned gold mine despite the obvious dangers.)"),
    ("cursory", "yuzaki, shoshma-shosharlik bilan", "B2", "42", "(adj.) brief to the point of being superficial (Late for the meeting, she cast a cursory glance at the agenda.)"),
    ("daunting", "cho'chituvchi, og'ir (vazifa)", "B2", "42", "(adj.) intimidating, causing one to lose courage (He kept delaying the daunting act of asking for a promotion.)"),
    ("debacle", "sharmandali mag'lubiyat, barbodlik", "B2", "42", "(n.) a disastrous failure, disruption (The elaborately designed fireworks show turned into a debacle when the fireworks started firing in random directions.)"),
    ("curt", "qisqa-qo'pol, sovuq (javob)", "B2", "42", "(adj.) abruptly and rudely short (Her curt reply to my question made me realize that she was upset at me.)"),
    ("debase", "qadrini tushirmoq, buzmoq", "B2", "42", "(v.) to lower the quality or esteem of something (The large raise that he gave himself debased his motives for running the charity.)"),
    ("debauch", "buzmoq, axloqsizlikka boshlamoq", "B2", "42", "(v.) to corrupt by means of sensual pleasures (An endless amount of good wine and cheese debauched the traveler.)"),
    ("debunk", "fosh qilmoq, puchligini ko'rsatmoq", "B2", "42", "(v.) to expose the falseness of something (He debunked her claim to be the world’s greatest chess player by defeating her in 18 consecutive matches.)"),
    ("decorous", "odobli, o'rinli", "B2", "42", "(adj.) socially proper, appropriate (The appreciative guest displayed decorous behavior toward his host.)"),
    ("decry", "qoralamoq, ayblamoq", "B2", "42", "(v.) to criticize openly (The kind video rental clerk decried the policy of charging customers late fees.)"),
    ("deface", "yuzini buzmoq, rasvo qilmoq", "B2", "42", "(v.) to ruin or injure something’s appearance (The brothers used eggs and shaving cream to deface their neighbor’s mailbox.)"),
    ("defamatory", "obro'ga putur yetkazuvchi, tuhmatli", "B2", "42", "(adj.) harmful toward another’s reputation (The defamatory gossip spreading about the actor made the public less willing to see the actor’s new movie.)"),
    ("deferential", "hurmat-ehtiromli", "B2", "42", "(adj.) showing respect for another’s authority (His deferential attitude toward her made her more confident in her ability to run the company.)"),
    ("defile", "bulg'amoq, harom qilmoq", "B2", "42", "(v.) to make unclean, impure (She defiled the calm of the religious building by playing her banjo.)"),
    ("deft", "chaqqon, mohir", "B2", "42", "(adj.) skillful, capable (Having worked in a bakery for many years, Marcus was a deft bread maker.)"),
    ("defunct", "amaldan qolgan, o'lik", "B2", "42", "(adj.) no longer used or existing (They planned to turn the defunct schoolhouse into a community center.)"),
    ("delegate", "vakil qilmoq; vakil", "B2", "42", "(v.) to hand over responsibility for something (The dean delegated the task of finding a new professor to a special hiring committee.)"),
    ("deleterious", "zararli, ziyonli", "B2", "42", "(adj.) harmful (She experienced the deleterious effects of running a marathon without stretching her muscles enough beforehand.)"),
    ("delineate", "aniq tasvirlamoq, belgilamoq", "B2", "42", "(v.) to describe, outline, shed light on (She neatly delineated her reasons for canceling the project’s funding.)"),
    # ---- Unit 43 (B2) ----
    ("demagogue", "avom his-tuyg'usini o'ynatuvchi siyosatchi, demagog", "B2", "43", "(n.) a leader who appeals to a people’s prejudices (The demagogue strengthened his hold over his people by blaming immigrants for the lack of jobs.)"),
    ("demarcation", "chegaralash, ajratish chizig'i", "B2", "43", "(n.) the marking of boundaries or categories (Different cultures have different demarcations of good and evil.)"),
    ("demean", "kamsitmoq, obro'sini to'kmoq", "B2", "43", "(v.) to lower the status or stature of something (She refused to demean her secretary by making him order her lunch.)"),
    ("demure", "iboli, kamsuqum", "B2", "43", "(adj.) quiet, modest, reserved (Though everyone else at the party was dancing and going crazy, she remained demure.)"),
    ("denigrate", "qoralamoq, bulg'amoq", "B2", "43", "(v.) to belittle, diminish the opinion of (The company decided that its advertisements would no longer denigrate the company’s competitors.)"),
    ("denounce", "oshkora qoralamoq, fosh etmoq", "B2", "43", "(v.) to criticize publicly (The senator denounced her opponent as a greedy politician.)"),
    ("deplore", "qattiq afsuslanmoq, qoralamoq", "B2", "43", "(v.) to feel or express sorrow, disapproval (We all deplored the miserable working conditions in the factory.)"),
    ("depravity", "buzuqlik, axloqsizlik", "B2", "43", "(n.) wickedness (Rumors of the ogre’s depravity made the children afraid to enter the forest.)"),
    ("deprecate", "ma'qullamaslik, qoralamoq", "B2", "43", "(v.) to belittle, depreciate (Always over-modest, he deprecated his contribution to the local charity.)"),
    ("deride", "masxara qilmoq, kulmoq", "B2", "43", "(v.) to laugh at mockingly, scorn (The bullies derided the foreign student’s accent.)"),
    ("desecrate", "muqaddas narsani bulg'amoq", "B2", "43", "(v.) to violate the sacredness of a thing or place (They feared that the construction of a golf course would desecrate the preserved wilderness.)"),
    ("desiccated", "qurigan, suvsizlangan", "B2", "43", "(adj.) dried up, dehydrated (The skin of the desiccated mummy looked like old paper.)"),
    ("desolate", "huvillagan, kimsasiz", "B2", "43", "(adj.) deserted, dreary, lifeless (She found the desolate landscape quite a contrast to the hustle and bustle of the overcrowded city.)"),
    ("derivative", "o'zgadan olingan, taqlidiy", "B2", "43", "(adj.) taken directly from a source, unoriginal (She was bored by his music because she felt that it was derivative and that she had heard it before.)"),
    ("despondent", "umidsiz, ruhi tushgan", "B2", "43", "(adj.) feeling depressed, discouraged, hopeless (Having failed the first math test, the despondent child saw no use in studying for the next and failed that one too.)"),
    ("despot", "zolim hukmdor, mustabid", "B2", "43", "(n.) one who has total power and rules brutally (The despot issued a death sentence for anyone who disobeyed his laws.)"),
    ("destitute", "qashshoq, bechorahol", "B2", "43", "(adj.) impoverished, utterly lacking (The hurricane destroyed many homes and left many families destitute.)"),
    ("deter", "qaytarmoq, to'sqinlik qilmoq", "B2", "43", "(v.) to discourage, prevent from doing (Bob’s description of scary snakes couldn’t deter Marcia from traveling in the rainforests.)"),
    ("devious", "hiylakor, egri yo'lli", "B2", "43", "(adj.) not straightforward, deceitful (Not wanting to be punished, the devious girl blamed the broken vase on the cat.)"),
    ("dialect", "sheva, lahja", "B2", "43", "(n.) a variation of a language (In the country’s remote, mountainous regions, the inhabitants spoke a dialect that the country’s other inhabitants had difficulty understanding.)"),
    ("diaphanous", "shaffof, harir", "B2", "43", "(adj.) light, airy, transparent (Sunlight poured in through the diaphanous curtains, brightening the room.)"),
    ("didactic", "o'rgatuvchi, pandnoma uslubidagi", "B2", "43", "1. (adj.) intended to instruct (She wrote up a didactic document showing new employees how to handle the company’s customers.) 2. (adj.) overly moralistic (His didactic style of teaching made it seem like he wanted to persuade his students not to understand history fully, but to understand it from only one point of view.)"),
    ("diffident", "o'ziga ishonmaydigan, tortinchoq", "B2", "43", "(adj.) shy, quiet, modest (While eating dinner with the adults, the diffident youth did not speak for fear of seeming presumptuous.)"),
    ("diffuse", "tarqalmoq, yoyilmoq; tarqoq", "B2", "43", "1. (v.) to scatter, thin out, break up (He diffused the tension in the room by making in a joke.) 2. (adj.) not concentrated, scattered, disorganized (In her writings, she tried unsuccessfully to make others understand her diffuse thoughts.)"),
    ("dilatory", "sustkash, paysalga soluvchi", "B2", "43", "(adj.) tending to delay, causing delay (The general’s dilatory strategy enabled the enemy to regroup.)"),
    ("diligent", "tirishqoq, mehnatsevar", "B2", "43", "(adj.) showing care in doing one’s work (The diligent researcher made sure to check her measurements multiple times.)"),
    ("diminutive", "juda kichik, mitti", "B2", "43", "(adj.) small or miniature (The bullies, tall and strong, picked on the diminutive child.)"),
    ("dirge", "motam qo'shig'i, marsiya", "B2", "43", "(n.) a mournful song, especially for a funeral (The bagpipers played a dirge as the casket was carried to the cemetery.)"),
    ("disaffected", "norozi, ixlosi qaytgan", "B2", "43", "(adj.) rebellious, resentful of authority (Dismayed by Bobby’s poor behavior, the parents sent their disaffected son to a military academy to be disciplined.)"),
    ("disavow", "tonmoq, rad etmoq", "B2", "43", "(v.) to deny knowledge of or responsibility for (Not wanting others to criticize her, she disavowed any involvement in the company’s hiring scandal.)"),
    ("discern", "ilg'amoq, farqlamoq", "B2", "43", "(v.) to perceive, detect (Though he hid his emotions, she discerned from his body language that he was angry.)"),
    ("disclose", "oshkor qilmoq, ochmoq", "B2", "43", "(v.) to reveal, make public (The CEO disclosed to the press that the company would have to fire several employees.)"),
    ("discomfit", "dovdiratmoq, xijolatga solmoq", "B2", "43", "(v.) to thwart, baffle (The normally cheery and playful children’s sudden misery discomfited the teacher.)"),
    ("discordant", "nomutanosib, g'ijillagan", "B2", "43", "(adj.) not agreeing, not in harmony with (The girls’ sobs were a discordant sound amid the general laughter that filled the restaurant.)"),
    ("discrepancy", "nomuvofiqlik, tafovut", "B2", "43", "(n.) difference, failure of things to correspond (He was troubled by the discrepancy between what he remembered paying for the appliance and what his receipt showed he paid for it.)"),
    ("discretion", "ehtiyotkorlik; ixtiyor", "B2", "43", "(n.) the quality of being reserved in speech or action; good judgment (Not wanting her patient to get overly anxious, the doctor used discretion in deciding how much to tell the patient about his condition.)"),
    ("discursive", "mavzudan chalg'ib ketuvchi, sochma", "B2", "43", "(adj.) rambling, lacking order (The professor’s discursive lectures seemed to be about every subject except the one initially described.)"),
    ("disgruntled", "norozi, arazlagan", "B2", "43", "(adj.) upset, not content (The child believed that his parents had unjustly grounded him, and remained disgruntled for a week.)"),
    ("disheartened", "ruhi tushgan, hafsalasi pir bo'lgan", "B2", "43", "(adj.) feeling a loss of spirit or morale (The team was disheartened after losing in the finals of the tournament.)"),
    # ---- Unit 44 (B2) ----
    ("disparage", "kamsitmoq, past baholamoq", "B2", "44", "(v.) to criticize or speak ill of (The saleswoman disparaged the competitor’s products to persuade her customers to buy what she was selling.)"),
    ("disdain", "mensimaslik, nazarga ilmaslik", "B2", "44", "1. (v.) to scorn, hold in low esteem (Insecure about their jobs, the older employees disdained the recently hired ones, who were young and capable.) 2. (n.) scorn, low esteem (After learning of his immoral actions, Justine held Lawrence in disdain.)"),
    ("dispatch", "jo'natmoq; tezkorlik", "B2", "44", "(v.) to send off to accomplish a duty (The carpenter dispatched his assistant to fetch wood.)"),
    ("dispel", "tarqatib yubormoq (shubha, qo'rquv)", "B2", "44", "(v.) to drive away, scatter (She entered the office as usual on Monday, dispelling the rumor that she had been fired.)"),
    ("disrepute", "obro'sizlik, badnomlik", "B2", "44", "(n.) a state of being held in low regard (The officer fell into disrepute after it was learned that he had disobeyed the orders he had given to his own soldiers.)"),
    ("dissemble", "yashirmoq, o'zini boshqacha ko'rsatmoq", "B2", "44", "(v.) to conceal, fake (Not wanting to appear heartlessly greedy, she dissembled and hid her intention to sell her ailing father’s stamp collection.)"),
    ("disseminate", "yoymoq, tarqatmoq (g'oya, ma'lumot)", "B2", "44", "(v.) to spread widely (The politician disseminated his ideas across the town before the election.)"),
    ("dissent", "norozilik bildirmoq; qarshi fikr", "B2", "44", "1. (v.) to disagree (The principal argued that the child should repeat the fourth grade, but the unhappy parents dissented.) 2. (n.) the act of disagreeing (Unconvinced that the defendant was guilty, the last juror voiced his dissent with the rest of the jury.)"),
    ("dissipate", "tarqalib yo'qolmoq; sovurmoq", "B2", "44", "1. (v.) to disappear, cause to disappear (The sun finally came out and dissipated the haze.) 2. (v.) to waste (She dissipated her fortune on a series of bad investments.)"),
    ("dissonance", "nomutanosiblik, ohangsizlik", "B2", "44", "(n.) lack of harmony or consistency (Though the president of the company often spoke of the company as reliant solely upon its workers, her decision to increase her own salary rather than reward her employees revealed a striking dissonance between her alleged beliefs and her actions.)"),
    ("dissuade", "fikridan qaytarmoq", "B2", "44", "(v.) to persuade someone not to do something (Worried that he would catch a cold, she tried to dissuade him from going out on winter nights.)"),
    ("distend", "shishmoq, kengaymoq", "B2", "44", "(v.) to swell out (Years of drinking beer caused his stomach to distend.)"),
    ("dither", "ikkilanmoq, sarosimada qolmoq", "B2", "44", "(v.) to be indecisive (Not wanting to offend either friend, he dithered about which of the two birthday parties he should attend.)"),
    ("divine", "ilohiy; oldindan sezmoq", "B2", "44", "(adj.) godly, exceedingly wonderful (Terribly fond of desserts, she found the rich chocolate cake to be divine.)"),
    ("divisive", "bo'lib tashlovchi, nizo qo'zg'ovchi", "B2", "44", "(adj.) causing dissent, discord (Her divisive tactics turned her two friends against each other.)"),
    ("divulge", "sirni ochmoq, oshkor qilmoq", "B2", "44", "(v.) to reveal something secret (Pressured by the press, the government finally divulged the previously unknown information.)"),
    ("docile", "yuvosh, gapga kiruvchi", "B2", "44", "(adj.) easily taught or trained (She successfully taught the docile puppy several tricks.)"),
    ("dogmatic", "aqidaparast, o'z fikrini mutlaq deb biluvchi", "B2", "44", "(adj.) aggressively and arrogantly certain about unproved principles (His dogmatic claim that men were better than women at fixing appliances angered everyone.)"),
    ("dormant", "uyquda bo'lgan, harakatsiz", "B2", "44", "(adj.) sleeping, temporarily inactive (Though she pretended everything was fine, her anger lay dormant throughout the dinner party and exploded in screams of rage after everyone had left.)"),
    ("dour", "qovog'i soliq, ma'yus", "B2", "44", "(adj.)stern, joyless (The children feared their dour neighbor because the old man would take their toys if he believed they were being too loud.)"),
    ("dubious", "shubhali, gumonli", "B2", "44", "(adj.) doubtful, of uncertain quality (Suspicious that he was only trying to get a raise, she found his praise dubious.)"),
    ("duplicity", "ikkiyuzlamachilik, munofiqlik", "B2", "44", "(n.) crafty dishonesty (His duplicity involved convincing his employees to let him lower their salaries and increase their stock options, and then to steal the money he saved and run the company into the ground.)"),
    ("duress", "majburlash, tazyiq", "B2", "44", "(n.) hardship, threat (It was only under intense duress that he, who was normally against killing, fired his gun.)"),
    ("dynamic", "serharakat, o'zgaruvchan; shijoatli", "B2", "44", "(adj.) actively changing (The parents found it hard to keep up with the dynamic music scene with which their children had become very familiar.)"),
    ("ebullient", "quvnoq, jo'shqin", "B2", "44", "(adj.) extremely lively, enthusiastic (She became ebullient upon receiving an acceptance letter from her first-choice college.)"),
    ("eclectic", "har xil manbalardan tanlangan, rang-barang", "B2", "44", "(adj.) consisting of a diverse variety of elements (That bar attracts an eclectic crowd: lawyers, artists, circus clowns, and investment bankers.)"),
    ("ecstatic", "behad xursand, o'zida yo'q", "B2", "44", "(adj.) intensely and overpoweringly happy (The couple was ecstatic when they learned that they had won the lottery.)"),
    ("edict", "farmon, buyruq", "B2", "44", "(n.) an order, decree (The ruler issued an edict requiring all of his subjects to bow down before him.)"),
    ("efface", "o'chirmoq, izini yo'qotmoq", "B2", "44", "(v.) to wipe out, obliterate, rub away (The husband was so angry at his wife for leaving him that he effaced all evidence of her presence; he threw out pictures of her and gave away all her belongings.)"),
    ("effervescent", "ko'pikli, gazli; quvnoq", "B2", "44", "(adj.) bubbly, lively (My friend is so effervescent that she makes everyone smile.)"),
    ("efficacious", "samarali, ta'sirchan", "B2", "44", "(adj.) effective (My doctor promised me that the cold medicine was efficacious, but I’m still sniffling.)"),
    ("effrontery", "surbetlik, betgachoparlik", "B2", "44", "(n.) impudence, nerve, insolence (When I told my aunt that she was boring, my mother scolded me for my effrontery.)"),
    ("effulgent", "porloq, nur sochuvchi", "B2", "44", "(adj.) radiant, splendorous (The golden palace was effulgent.)"),
    ("egregious", "o'ta yomon, ko'zga tashlanadigan darajada qo'pol", "B2", "44", "(adj.) extremely bad (The student who threw sloppy joes across the cafeteria was punished for his egregious behavior.)"),
    ("elaborate", "puxta ishlangan; batafsil bayon qilmoq", "B2", "44", "(adj.) complex, detailed, intricate (Dan always beats me at chess because he develops such an elaborate game plan that I can never predict his next move.)"),
    ("elated", "sevinchdan uchgan, shod", "B2", "44", "(adj.) overjoyed, thrilled (When she found out she had won the lottery, the writer was elated.)"),
    ("elegy", "marsiya, motam she'ri", "B2", "44", "(n.) a speech given in honor of a dead person (At the funeral, the widow gave a moving elegy describing her love for her husband.)"),
    ("elicit", "yuzaga chiqarmoq, so'rab olmoq", "B2", "44", "(v.) to bring forth, draw out, evoke (Although I asked several times where the exit was, I elicited no response from the stone-faced policeman.)"),
    # ---- Unit 45 (B2) ----
    ("eloquent", "notiq, so'zga chechan", "B2", "45", "(adj.) expressive, articulate, moving (The priest gave such an eloquent sermon that most churchgoers were crying.)"),
    ("elude", "qochib qutulmoq, tutqich bermaslik", "B2", "45", "(v.) to evade, escape (Despite an intense search, the robber continues to elude the police.)"),
    ("emaciated", "ozib-to'zib ketgan, qoq suyak", "B2", "45", "(adj.) very thin, enfeebled looking (My sister eats a lot of pastries and chocolate but still looks emaciated.)"),
    ("embezzle", "o'zlashtirmoq, xazinani yemoq", "B2", "45", "(v.) to steal money by falsifying records (The accountant was fired for embezzling $10,000 of the company’s funds.)"),
    ("emend", "tuzatmoq, to'g'rilamoq (matnni)", "B2", "45", "(v.) to correct or revise a written text (If my sentence is incorrect, the editor will emend what I have written.)"),
    ("eminent", "atoqli, ko'zga ko'ringan", "B2", "45", "1. (adj.) distinguished, prominent, famous (Mr. Phillips is such an eminent scholar that every professor on campus has come to hear him lecture.) 2. (adj.) conspicuous (There is an eminent stain on that shirt.)"),
    ("emollient", "yumshatuvchi (vosita)", "B2", "45", "(adj.) soothing (This emollient cream makes my skin very smooth.)"),
    ("emote", "his-tuyg'ularini namoyish qilmoq", "B2", "45", "(v.) to express emotion (The director told the actor he had to emote, or else the audience would have no idea what his character was going through.)"),
    ("empathy", "hamdardlik, o'zini o'rniga qo'ya bilish", "B2", "45", "(n.) sensitivity to another’s feelings as if they were one’s own (I feel such empathy for my sister when she’s in pain that I cry too.)"),
    ("empirical", "tajribaga asoslangan, empirik", "B2", "45", "1. (adj.) based on observation or experience (The scientist gathered empirical data on the growth rate of dandelions by studying the dandelions behind his house.) 2. (adj.) capable of being proved or disproved by experiment (That all cats hate getting wet is an empirical statement: I can test it by bathing my cat, Trinket.)"),
    ("emulate", "o'rnak olib intilmoq, taqlid qilmoq", "B2", "45", "(v.) to imitate (I idolize Britney Spears so much that I emulate everything she does: I wear her outfits, sing along to her songs, and date a boy named Justin.)"),
    ("enamor", "oshiq qilmoq, maftun etmoq", "B2", "45", "(v.) to fill with love, fascinate, usually used in passive form followed by “of” or “with” (I grew enamored of that boy when he quoted my favorite love poem.)"),
    ("encumber", "yuklamoq, og'irlik qilmoq", "B2", "45", "(v.) to weigh down, burden (At the airport, my friend was encumbered by her luggage, so I offered to carry two of her bags.)"),
    ("enervate", "holdan toydirmoq, kuchsizlantirmoq", "B2", "45", "(v.) to weaken, exhaust (Writing these sentences enervates me so much that I will have to take a nap after I finish.)"),
    ("enfranchise", "saylov huquqi bermoq, ozod qilmoq", "B2", "45", "(v.) to grant the vote to (The Nineteenth Amendment enfranchised women.)"),
    ("engender", "keltirib chiqarmoq, tug'dirmoq", "B2", "45", "(v.) to bring about, create, generate (During the Olympics, the victories of U.S. athletes engender a patriotic spirit among Americans.)"),
    ("enigmatic", "sirli, jumboqli", "B2", "45", "(adj.) mystifying, cryptic (That man wearing the dark suit and dark glasses is so enigmatic that no one even knows his name.)"),
    ("encore", "chiqishni takrorlash, bis", "B2", "45", "(n.) the audience’s demand for a repeat performance; also the artist’s performance in response to that demand (At the end of the concert, all the fans yelled, “Encore! Encore!” but the band did not come out to play again.)"),
    ("enmity", "adovat, dushmanlik", "B2", "45", "(n.) ill will, hatred, hostility (Mark and Andy have clearly not forgiven each other, because the enmity between them is obvious to anyone in their presence.)"),
    ("ennui", "zerikish, ma'nisizlikdan siqilish", "B2", "45", "(n.) boredom, weariness (I feel such ennui that I don’t look forward to anything, not even my birthday party.)"),
    ("entail", "taqozo etmoq, keltirib chiqarmoq", "B2", "45", "(v.) to include as a necessary step (Building a new fence entails tearing down the old one.)"),
    ("enthrall", "rom qilmoq, sehrlamoq", "B2", "45", "(v.) to charm, hold spellbound (The sailor’s stories of fighting off sharks and finding ancient treasures enthralled his young son.)"),
    ("ephemeral", "o'tkinchi, qisqa umrli", "B2", "45", "(adj.) short-lived, fleeting (She promised she’d love me forever, but her “forever” was only ephemeral: she left me after one week.)"),
    ("epistolary", "maktublardan iborat, xat-yozishmalarga oid", "B2", "45", "(adj.) relating to or contained in letters (Some people call me “Auntie’s boy,” because my aunt and I have such a close epistolary relationship that we write each other every day.)"),
    ("epitome", "yorqin timsol, mujassam namuna", "B2", "45", "(n.) a perfect example, embodiment (My mother, the epitome of good taste, always dresses more elegantly than I do.)"),
    ("equanimity", "xotirjamlik, vazminlik", "B2", "45", "(n.) composure (Even though he had just been fired, Mr. Simms showed great equanimity by neatly packing up his desk and wishing everyone in the office well.)"),
    ("equivocal", "ikki ma'noli, mavhum", "B2", "45", "(adj.) ambiguous, uncertain, undecided (His intentions were so equivocal that I didn’t know whether he was being chivalrous or sleazy.)"),
    ("erudite", "bilimdon, olim", "B2", "45", "(adj.) learned (My Latin teacher is such an erudite scholar that he has translated some of the most difficult and abstruse ancient poetry.)"),
    ("eschew", "chetlab o'tmoq, o'zini tiymoq", "B2", "45", "(v.) to shun, avoid (George hates the color green so much that he eschews all green food.)"),
    ("esoteric", "faqat xoslarga tushunarli, yopiq", "B2", "45", "(adj.) understood by only a select few (Even the most advanced students cannot understand the physicist’s esoteric theories.)"),
    ("espouse", "qo'llab-quvvatlamoq, tarafdori bo'lmoq", "B2", "45", "(v.) to take up as a cause, support (I love animals so much that I espouse animal rights.)"),
    ("ethereal", "nozik, samoviy", "B2", "45", "(adj.) heavenly, exceptionally delicate or refined (In her flowing silk gown and lace veil, the bride looked ethereal.)"),
    ("etymology", "so'zning kelib chiqishi, etimologiya", "B2", "45", "(n.) the history of words, their origin and development (From the study of etymology, I know that the word “quixotic” derives from Don Quixote and the word “gaudy” refers to the Spanish architect Gaudí.)"),
    ("euphoric", "behad shod, sarxush", "B2", "45", "(adj.) elated, uplifted (I was euphoric when I found out that my sister had given birth to twins.)"),
    ("evanescent", "tez g'oyib bo'luvchi, o'tkinchi", "B2", "45", "(adj.) fleeting, momentary (My joy at getting promoted was evanescent because I discovered that I would have to work much longer hours in a less friendly office.)"),
    ("evince", "namoyon qilmoq, ko'rsatmoq", "B2", "45", "(v.) to show, reveal (Christopher’s hand-wringing and nail-biting evince how nervous he is about the upcoming English test.)"),
    ("exalt", "ulug'lamoq, ko'klarga ko'tarmoq", "B2", "45", "(v.) to glorify, praise (Michael Jordan is the figure in basketball we exalt the most.)"),
    # ---- Unit 46 (B2) ----
    ("exasperate", "jahlini chiqarmoq, sabrini tugatmoq", "B2", "46", "(v.) to irritate, irk (George’s endless complaints exasperated his roomate.)"),
    ("excavate", "qazimoq, kavlab ochmoq", "B2", "46", "(v.) to dig out of the ground and remove (The pharaoh’s treasures were excavated by archeologists in Egypt.)"),
    ("exculpate", "aybdan oqlamoq", "B2", "46", "(v.) to free from guilt or blame, exonerate (My discovery of the ring behind the dresser exculpated me from the charge of having stolen it.)"),
    ("excursion", "sayohat, ekskursiya", "B2", "46", "(n.) a trip or outing (After taking an excursion to the Bronx Zoo, I dreamed about pandas and monkeys.)"),
    ("execrable", "jirkanch, o'ta yomon", "B2", "46", "(adj.) loathsome, detestable (Her pudding is so execrable that it makes me sick.)"),
    ("exonerate", "aybsiz deb topmoq, oqlamoq", "B2", "46", "(v.) to free from guilt or blame, exculpate (The true thief’s confession exonerated the man who had been held in custody for the crime.)"),
    ("exorbitant", "haddan tashqari qimmat, o'ta yuqori", "B2", "46", "(adj.) excessive (Her exorbitant praise made me blush and squirm in my seat.)"),
    ("expedient", "qulay, manfaatli (vaqtincha yechim)", "B2", "46", "(adj.) advisable, advantageous, serving one’s self-interest (In his bid for reelection, the governor made an expedient move by tabling all controversial legislation.)"),
    ("expiate", "gunohini yuvmoq", "B2", "46", "(v.) to make amends for, atone (To expiate my selfishness, I gave all my profits to charity.)"),
    ("exigent", "kechiktirib bo'lmas, dolzarb", "B2", "46", "(adj.) urgent, critical (The patient has an exigent need for medication, or else he will lose his sight.)"),
    ("expunge", "o'chirib tashlamoq, yo'q qilmoq", "B2", "46", "(v.) to obliterate, eradicate (Fearful of an IRS investigation, Paul tried to expunge all incriminating evidence from his tax files.)"),
    ("expurgate", "nomaqbul joylarini olib tashlamoq, tozalamoq", "B2", "46", "(v.) to remove offensive or incorrect parts, usually of a book (The history editors expurgated from the text all disparaging and inflammatory comments about the Republican Party.)"),
    ("extant", "hozirgacha saqlanib qolgan, mavjud", "B2", "46", "(adj.) existing, not destroyed or lost (My mother’s extant love letters to my father are in the attic trunk.)"),
    ("extol", "maqtamoq, madh etmoq", "B2", "46", "(v.) to praise, revere (Violet extolled the virtues of a vegetarian diet to her meatloving brother.)"),
    ("extraneous", "aloqasiz, ortiqcha", "B2", "46", "(adj.) irrelevant, extra, not necessary (Personal political ambitions should always remain extraneous to legislative policy, but, unfortunately, they rarely are.)"),
    ("extricate", "chiqarib olmoq, xalos qilmoq", "B2", "46", "(v.) to disentangle (Instead of trying to mediate between my brother and sister, I extricated myself from the family tension entirely and left the house for the day.)"),
    ("exult", "shodlanmoq, tantana qilmoq", "B2", "46", "(v.) to rejoice (When she found out she won the literature prize, Mary exulted by dancing and singing through the school’s halls.)"),
    ("fabricate", "to'qib chiqarmoq; yasamoq", "B2", "46", "(v.) to make up, invent (When I arrived an hour late to class, I fabricated some excuse about my car breaking down on the way to school.) façade 1. (n.) the wall of a building (Meet me in front of the museum’s main façade.) 2. (n.) a deceptive appearance or attitude (Despite my smiling façade, I am feeling melancholy.)"),
    ("facile", "yuzaki oson, sayoz", "B2", "46", "1. (adj.) easy, requiring little effort (This game is so facile that even a four-yearold can master it.) 2. (adj.) superficial, achieved with minimal thought or care, insincere (The business was in such shambles that any solution seemed facile at best; nothing could really helpit in the long-run.)"),
    ("fallacious", "noto'g'ri, yanglish (mantiqan)", "B2", "46", "(adj.) incorrect, misleading (Emily offered me cigarettes on the fallacious assumption that I smoked.)"),
    ("fathom", "tushunib yetmoq, aql bovar qilmoq", "B2", "46", "(v.) to understand, comprehend (I cannot fathom why you like that crabby and mean-spirited neighbor of ours.)"),
    ("fatuous", "befarosat, ahmoqona", "B2", "46", "(adj.) silly, foolish (He considers himself a serious poet, but in truth, he only writes fatuous limericks.)"),
    ("fecund", "serhosil, sermahsul", "B2", "46", "(adj.) fruitful, fertile (The fecund tree bore enough apples to last us through the entire season.)"),
    ("felicitous", "juda o'rinli, muvaffaqiyatli", "B2", "46", "1. (adj.) well suited, apt (While his comments were idiotic and rambling, mine were felicitous and helpful.) 2. (adj.) delightful, pleasing (I spent a felicitous afternoon visiting old friends.)"),
    ("feral", "yovvoyi, yovvoyilashgan", "B2", "46", "(adj.) wild, savage (That beast looks so feral that I would fear being alone with it.)"),
    ("fervent", "otashin, qizg'in", "B2", "46", "(adj.) ardent, passionate (The fervent protestors chained themselves to the building and shouted all night long.)"),
    ("fetid", "sassiq, badbo'y", "B2", "46", "(adj.) having a foul odor (I can tell from the fetid smell in your refrigerator that your milk has spoiled.)"),
    ("fetter", "kishanlamoq, oyog'iga tushov solmoq", "B2", "46", "(v.) to chain, restrain (The dog was fettered to the parking meter.)"),
    ("fickle", "subutsiz, tez o'zgaruvchan", "B2", "46", "(adj.) shifting in character, inconstant (In Greek dramas, the fickle gods help Achilles one day, and then harm him the next.)"),
    ("fidelity", "sadoqat, vafo", "B2", "46", "(n.) loyalty, devotion (Guard dogs are known for the great fidelity they show toward their masters.)"),
    ("figurative", "ko'chma ma'nodagi, majoziy", "B2", "46", "(adj.) symbolic (Using figurative language, Jane likened the storm to an angry bull.)"),
    ("flabbergasted", "hayratdan qotib qolgan, dong qotgan", "B2", "46", "(adj.) astounded (Whenever I read an Agatha Christie mystery novel, I am always flabbergasted when I learn the identity of the murderer.)"),
    ("flagrant", "ochiqdan-ochiq, sharmandali", "B2", "46", "(adj.) offensive, egregious (The judge’s decision to set the man free simply because that man was his brother was a flagrant abuse of power.)"),
    ("florid", "chaman, serhasham; qizil yuzli", "B2", "46", "(adj.) flowery, ornate (The writer’s florid prose belongs on a sentimental Hallmark card.)"),
    ("flout", "mensimay buzmoq, pisand qilmaslik", "B2", "46", "(v.) to disregard or disobey openly (I flouted the school’s dress code by wearing a tie-dyed tank top and a pair of cut-off jeans.)"),
    ("foil", "rejasini puchga chiqarmoq", "B2", "46", "(v.) to thwart, frustrate, defeat (Inspector Wilkens foiled the thieves by locking them in the bank along with their stolen money.)"),
    ("flaccid", "bo'shashgan, shalvirab qolgan", "B2", "46", "(adj.) limp, not firm or strong (If a plant is not watered enough, its leaves become droopy and flaccid.)"),
    ("forage", "yem-xashak izlamoq, titkilab izlamoq", "B2", "46", "(v.) to graze, rummage for food (When we got lost on our hiking trip, we foraged for berries and nuts in order to survive.)"),
    # ---- Unit 47 (B2) ----
    ("forbearance", "sabr-toqat, o'zini tiyish", "B2", "47", "(n.) patience, restraint, toleration (The doctor showed great forbearance in calming down the angry patient who shouted insults at him.)"),
    ("forestall", "oldini olmoq", "B2", "47", "(v.) to prevent, thwart, delay (I forestalled the cold I was getting by taking plenty of vitamin C pills and wearing a scarf.)"),
    ("forlorn", "g'arib, tashlab qo'yilgan", "B2", "47", "(adj.) lonely, abandoned, hopeless (Even though I had the flu, my family decided to go skiing for the weekend and leave me home alone, feeling feverish and forlorn.)"),
    ("forsake", "tark etmoq, voz kechmoq", "B2", "47", "(v.) to give up, renounce (My New Year’s resolution is to forsake smoking and drinking.)"),
    ("fortuitous", "tasodifiy omadli, kutilmagan baxtli", "B2", "47", "(adj.) happening by chance, often lucky or fortunate (After looking for Manuel and not finding him at home, Harriet had a fortuitous encounter with him at the post office.)"),
    ("forum", "muhokama maydoni, minbar", "B2", "47", "(n.) a medium for lecture or discussion (Some radio talk-shows provide a good forum for political debate.)"),
    ("foster", "rivojlantirmoq, tarbiyalamoq", "B2", "47", "(v.) to stimulate, promote, encourage (To foster good health in the city, the mayor started a “Get out and exercise!” campaign.)"),
    ("fractious", "injiq, arazchi, gap ko'tarmas", "B2", "47", "(adj.) troublesome or irritable (Although the child insisted he wasn’t tired, his fractious behavior—especially his decision to crush his cheese and crackers all over the floor—convinced everyone present that it was time to put him to bed.)"),
    ("fraught", "to'la, limmo-lim (xavfga)", "B2", "47", "(adj.) (usually used with “with”) filled or accompanied with (Her glances in his direction were fraught with meaning, though precisely what meaning remained unclear.)"),
    ("frenetic", "telbavor shiddatli, betartib jadal", "B2", "47", "(adj.) frenzied, hectic, frantic (In the hours between night and morning, the frenetic pace of city life slows to a lull.)"),
    ("frivolous", "yengiltak, bema'ni", "B2", "47", "(adj.) of little importance, trifling (Someday, all that anxiety about whether your zit will disappear before the prom will seem totally frivolous.)"),
    ("frugal", "tejamkor", "B2", "47", "(adj.) thrifty, economical (Richard is so frugal that his diet consists almost exclusively of catfish and chicken liver—the two most inexpensive foods in the store.)"),
    ("furtive", "o'g'rincha, yashirin", "B2", "47", "(adj.) secretive, sly (Jane’s placement of her drugs in her sock drawer was not as furtive as she thought, as the sock drawer is the first place most parents look.)"),
    ("garish", "chirsildoq yorqin, ko'zni qamashtiruvchi", "B2", "47", "(adj.) gaudy, in bad taste (Mrs. Watson has poor taste and covers every object in her house with a garish gold lamé.)"),
    ("garrulous", "sergap, valdiroq", "B2", "47", "(adj.) talkative, wordy (Some talk show hosts are so garrulous that their guests can’t get a word in edgewise.)"),
    ("genial", "ochiqko'ngil, iliq", "B2", "47", "(adj.) friendly, affable (Although he’s been known to behave like a real jerk, I would say that my brother is an overall genial guy.)"),
    ("gluttony", "ochofatlik, mechkaylik", "B2", "47", "(n.) overindulgence in food or drink (Ada’s fried chicken tastes so divine, I don’t know how anyone can call gluttony a sin.)"),
    ("goad", "gijgijlamoq, turtkilamoq", "B2", "47", "(v.) to urge, spur, incite to action (Jim may think he’s not going to fight Billy, but Billy will goad Jim on with insults until he throws a punch.)"),
    ("gourmand", "yeb-ichishga o'ch odam, ochofat", "B2", "47", "(n.) someone fond of eating and drinking (My parents, who used to eat little more than crackers and salad, have become real gourmands in their old age.)"),
    ("grandiloquence", "dabdabali balandparvoz gap", "B2", "47", "(n.) lofty, pompous language (The student thought her grandiloquence would make her sound smart, but neither the class nor the teacher bought it.)"),
    ("grandiose", "hashamatli, ulug'vor (ko'pincha soxta)", "B2", "47", "(adj.) on a magnificent or exaggerated scale (Margaret planned a grandiose party, replete with elephants, trapeze artists, and clowns.)"),
    ("gratuitous", "o'rinsiz, keraksiz; tekin", "B2", "47", "(adj.) uncalled for, unwarranted (Every morning the guy at the donut shop gives me a gratuitous helping of ketchup packets.)"),
    ("grievous", "og'ir, ayanchli", "B2", "47", "(adj.) injurious, hurtful; serious or grave in nature (Electrocuting the inmate without being sure of his guilt would be a truly grievous mistake.)"),
    ("guile", "hiyla, makkorlik", "B2", "47", "(n.) deceitful, cunning, sly behavior (Because of his great guile, the politician was able to survive scandal after scandal.)"),
    ("hackneyed", "siyqasi chiqqan, eskirgan (ibora)", "B2", "47", "(adj.) unoriginal, trite (A girl can only hear “I love you” so many times before it begins to sound hackneyed and meaningless.)"),
    ("gregarious", "davraboz, kirishimli", "B2", "47", "(adj.) drawn to the company of others, sociable (Well, if you’re not gregarious, I don’t know why you would want to go to a singles party!)"),
    ("hallowed", "muqaddas, tabarruk", "B2", "47", "(adj.) revered, consecrated (In the hallowed corridors of the cathedral, the disturbed professor felt himself to be at peace.)"),
    ("hapless", "omadsiz, bechora", "B2", "47", "(adj.) unlucky (My poor, hapless family never seems to pick a sunny week to go on vacation.)"),
    ("harangue", "uzun zerikarli nutq; do'q-po'pisali va'z", "B2", "47", "1. (n.) a ranting speech (Everyone had heard the teacher’s harangue about gum chewing in class before.) 2. (v.) to give such a speech (But this time the teacher harangued the class about the importance of brushing your teeth after chewing gum.)"),
    ("hardy", "chidamli, bardoshli", "B2", "47", "(adj.) robust, capable of surviving through adverse conditions (I too would have expected the plants to be dead by mid-November, but apparently they’re very hardy.)"),
    ("harrowing", "yurakni ezuvchi, dahshatli", "B2", "47", "(adj.) greatly distressing, vexing (The car crash was a harrowing experience, but I have a feeling that the increase in my insurance premiums will be even more upsetting.)"),
    ("haughty", "kibrli, dimog'dor", "B2", "47", "(adj.) disdainfully proud (The superstar’s haughty dismissal of her costars will backfire on her someday.)"),
    ("hedonist", "aysh-ishrat shaydosi, huzur-halovat izlovchi", "B2", "47", "(n.) one who believes pleasure should be the primary pursuit of humans (Because he’s such a hedonist, I knew Murray would appreciate the 11 cases of wine I bought him for his birthday.)"),
    ("hegemony", "yakkahokimlik, ustunlik", "B2", "47", "(n.) domination over others (Britain’s hegemony over its colonies was threatened once nationalist sentiment began to spread around the world.)"),
    ("heinous", "o'ta jirkanch, mudhish", "B2", "47", "(adj.) shockingly wicked, repugnant (The killings were made all the more heinous by the fact that the murderer first tortured his victims for three days.)"),
    ("heterogeneous", "har jinsli, aralash", "B2", "47", "(adj.) varied, diverse in character (I hate having only one flavor so I always buy the swirled, or should I say heterogeneous, type of ice cream.)"),
    ("hiatus", "tanaffus, uzilish", "B2", "47", "(n.) a break or gap in duration or continuity (The hiatus in service should last two or three months—until the cable lines are repaired .)"),
    ("hierarchy", "mansab pog'onasi, ierarxiya", "B2", "47", "(n.) a system with ranked groups, usually according to social, economic, or professional class (Women found it very difficult to break into the upper ranks of the department’s hierarchy.)"),
    ("hypocrisy", "ikkiyuzlamachilik, riyokorlik", "B2", "47", "(n.) pretending to believe what one does not (Once the politician began passing legislation that contradicted his campaign promises, his hypocrisy became apparent.)"),
    # ---- Unit 48 (B2) ----
    ("hypothetical", "faraziy, taxminiy", "B2", "48", "(adj.) supposed or assumed true, but unproven (Even though it has been celebrated by seven major newspapers, that the drug will be a success when tested in humans is still hypothetical.)"),
    ("iconoclast", "an'analarni buzuvchi, aqidalarga qarshi chiquvchi", "B2", "48", "(n.) one who attacks common beliefs or institutions (Jane goes to one protest after another, but she seems to be an iconoclast rather than an activist with a progressive agenda.)"),
    ("idiosyncratic", "o'ziga xos, g'alati odatli", "B2", "48", "(adj.) peculiar to one person; highly individualized (I know you had trouble with the last test, but because your mistakes were highly idiosyncratic, I’m going to deny your request that the class be given a new test.)"),
    ("idolatrous", "butparast, ko'r-ko'rona sig'inuvchi", "B2", "48", "(adj.) excessively worshipping one object or person (Xena’s idolatrous fawning over the band—following them on tour, starting their fan club, filming their documentary—is really beginning to get on my nerves.)"),
    ("ignominious", "sharmandali, or-nomusli", "B2", "48", "(adj.) humiliating, disgracing (It was really ignominious to be kicked out of the dorm for having an illegal gas stove in my room.)"),
    ("illicit", "noqonuniy, taqiqlangan", "B2", "48", "(adj.) forbidden, not permitted (The fourth-grader learned many illicit words from a pamphlet that was being passed around school.)"),
    ("immerse", "sho'ng'imoq, g'arq bo'lmoq", "B2", "48", "(v.) to absorb, deeply involve, engross (After breaking up with her boyfriend, Nancy decided to immerse herself in her work in order to avoid crying.)"),
    ("immutable", "o'zgarmas", "B2", "48", "(adj.) not changeable (The laws of physics are immutable and constant.)"),
    ("impassive", "his bildirmaydigan, befarq yuzli", "B2", "48", "(adj.) stoic, not susceptible to suffering (Stop being so impassive; it’s healthy to cry every now and then.)"),
    ("impecunious", "puli yo'q, qashshoq", "B2", "48", "(adj.) poor (“I fear he’s too impecunious to take me out tonight,” the bratty girl whined.)"),
    ("imperative", "shart, zarur; buyruq", "B2", "48", "1. (adj.) necessary, pressing (It is imperative that you have these folders organized by midday.) 2. (n.) a rule, command, or order (Her imperative to have the folders organized by midday was perceived as ridiculous by the others.)"),
    ("imperious", "buyruqboz, hukmfarmo", "B2", "48", "(adj.) commanding, domineering (The imperious nature of your manner led me to dislike you at once.)"),
    ("impeccable", "benuqson, mukammal", "B2", "48", "(adj.) exemplary, flawless (If your grades were as impeccable as your sister’s, then you too would receive a car for a graduation present.)"),
    ("impertinent", "beadab, surbet", "B2", "48", "(adj.) rude, insolent (Most of your comments are so impertinent that I don’t wish to dignify them with an answer.)"),
    ("impervious", "o'tkazmaydigan, ta'sirlanmaydigan", "B2", "48", "(adj.) impenetrable, incapable of being affected (Because of their thick layer of fur, many seals are almost impervious to the cold.)"),
    ("impetuous", "shiddatli, o'ylamay ish qiluvchi", "B2", "48", "(adj.) rash; hastily done (Hilda’s hasty slaying of the king was an impetuous, thoughtless action.)"),
    ("impinge", "daxl qilmoq, tajovuz qilmoq", "B2", "48", "1. (v.) to impact, affect, make an impression (The hail impinged the roof, leaving large dents.) 2. (v.) to encroach, infringe (I apologize for impinging upon you like this, but I really need to use your bathroom. Now.)"),
    ("implacable", "murosasiz, yumshatib bo'lmas", "B2", "48", "(adj.) incapable of being appeased or mitigated (Watch out: once you shun Grandma’s cooking, she is totally implacable.)"),
    ("implicit", "bevosita aytilmagan, nazarda tutilgan", "B2", "48", "(adj.) understood but not outwardly obvious, implied (I know Professor Smith didn’t actually say not to write from personal experience, but I think such a message was implicit in her instruction to use scholarly sources.)"),
    ("impregnable", "zabt etib bo'lmas, mustahkam", "B2", "48", "(adj.) resistant to capture or penetration (Though the invaders used battering rams, catapults, and rain dances, the fortress proved impregnable and resisted all attacks.)"),
    ("impudent", "beadab, yuzsiz", "B2", "48", "(adj.) casually rude, insolent, impertinent (The impudent young man looked the princess up and down and told her she was hot even though she hadn’t asked him.)"),
    ("impute", "ayb taqamoq, nisbat bermoq", "B2", "48", "(v.) to ascribe, blame (The CEO imputed the many typos in the letter to his lazy secretary.)"),
    ("inane", "bema'ni, puch", "B2", "48", "(adj.) silly and meaningless (Some films are so inane that the psychology of the characters makes absolutely no sense.)"),
    ("inarticulate", "tili chuchuk, fikrini ifodalay olmaydigan", "B2", "48", "(adj.) incapable of expressing oneself clearly through speech (Though he spoke for over an hour, the lecturer was completely inarticulate and the students had no idea what he was talking about.)"),
    ("incarnate", "gavdalangan, jonli timsol", "B2", "48", "1. (adj.) existing in the flesh, embodied (In the church pageant, I play the role of greed incarnate.) 2. (v.) to give human form to (The alien evaded detection by incarnating himself in a human form.)"),
    ("incendiary", "yong'in chiqaruvchi; nizo qo'zg'ovchi", "B2", "48", "1. (n.) a person who agitates (If we catch the incendiary who screamed “bomb” in the middle of the soccer match, we’re going to put him in jail.) 2. (adj.) inflammatory, causing combustion (Gas and lighter fluid are incendiary materials that should be kept out of hot storage areas.)"),
    ("incessant", "tinimsiz, uzluksiz", "B2", "48", "(adj.) unending (We wanted to go outside and play, but the incessant rain kept us indoors for two days.)"),
    ("inchoate", "endi shakllanayotgan, xom", "B2", "48", "(adj.) unformed or formless, in a beginning stage (The country’s government is still inchoate and, because it has no great tradition, quite unstable.)"),
    ("incisive", "o'tkir, teshib o'tuvchi (fikr)", "B2", "48", "(adj.) clear, sharp, direct (The discussion wasn’t going anywhere until her incisive comment allowed everyone to see what the true issues were.)"),
    ("inclination", "moyillik, xohish", "B2", "48", "(n.) a tendency, propensity (Sarah has an inclination to see every foreign film she hears about, even when she’s sure that she won’t like it.)"),
    ("incontrovertible", "inkor etib bo'lmas, shak-shubhasiz", "B2", "48", "(adj.) indisputable (Only stubborn Tina would attempt to disprove the incontrovertible laws of physics.)"),
    ("incorrigible", "tuzalmas, qaysar", "B2", "48", "(adj.) incapable of correction, delinquent (You can buy Grandma nicotine gum all you want, but I think that after sixty-five years of smoking she’s incorrigible.)"),
    ("increment", "orttirma, qo'shimcha o'sish", "B2", "48", "(n.) an enlargement; the process of increasing(The workmen made the wall longer, increment by increment.)"),
    ("indefatigable", "charchamas, tinim bilmas", "B2", "48", "(adj.) incapable of defeat, failure, decay (Even after traveling 62 miles, the indefatigable runner kept on moving.)"),
    ("indigent", "kambag'al, muhtoj", "B2", "48", "(adj.) very poor, impoverished (I would rather donate money to help the indigent population than to the park sculpture fund.)"),
    ("indignation", "adolatsizlikdan g'azablanish, nafrat", "B2", "48", "(n.) anger sparked by something unjust or unfair (I resigned from the sorority because of my indignation at its hazing of new members.)"),
    ("incumbent", "amaldagi (mansabdor); zimmasidagi burch", "B2", "48", "1. (n.) one who holds an office (The incumbent senator is already serving his fifth term.) 2. (adj.) obligatory (It is incumbent upon this organization to offer aid to all who seek it.)"),
    # ---- Unit 49 (C1) ----
    ("indolent", "dangasa, ishyoqmas", "C1", "49", "(adj.) lazy (Why should my indolent children, who can’t even pick themselves up off the couch to pour their own juice, be rewarded with a trip to the mall?)"),
    ("indomitable", "yengib bo'lmas, bukilmas", "C1", "49", "(adj.) not capable of being conquered (To be honest, Jim, my indomitable nature means I could never take orders from anyone, and especially not from a jerk like you.)"),
    ("ineffable", "so'z bilan ifodalab bo'lmas", "C1", "49", "(adj.) unspeakable, incapable of being expressed through words (It is said that the experience of playing with a dolphin is ineffable and can only be understood through direct encounter.)"),
    ("inept", "uquvsiz, no'noq", "C1", "49", "(adj.) not suitable or capable, unqualified (She proved how inept she was when she forgot three orders and spilled a beer in a customer’s lap.)"),
    ("inexorable", "to'xtatib bo'lmas, shafqatsiz", "C1", "49", "(adj.) incapable of being persuaded or placated (Although I begged for hours, Mom was inexorable and refused to let me stay out all night after the prom.)"),
    ("inextricable", "ajratib bo'lmas, chigal", "C1", "49", "(adj.) hopelessly tangled or entangled (Unless I look at the solution manual, I have no way of solving this inextricable problem.)"),
    ("infamy", "badnomlik, sharmandalik", "C1", "49", "(n.) notoriety, extreme ill repute (The infamy of his crime will not lessen as the decades pass.)"),
    ("infusion", "quyish, singdirish; damlama", "C1", "49", "(n.) an injection of one substance into another; the permeation of one substance by another (The infusion of Eastern religion into Western philosophy created interesting new schools of thought.)"),
    ("ingenuous", "sodda, samimiy", "C1", "49", "(adj.) not devious; innocent and candid (He must have writers, but his speeches seem so ingenuous it’s hard to believe he’s not speaking from his own heart.)"),
    ("inimical", "dushmanona, zid", "C1", "49", "(adj.) hostile, enemylike (I don’t see how I could ever work for a company that was so cold and inimical to me during my interviews.)"),
    ("iniquity", "adolatsizlik, gunohkorlik", "C1", "49", "(n.) wickedness or sin (“Your iniquity,” said the priest to the practical jokester, “will be forgiven.”)"),
    ("injunction", "sud taqiqi, buyruq", "C1", "49", "(n.) an order of official warning (After his house was toilet-papered for the fifth time, the mayor issued an injunction against anyone younger than 21 buying toilet paper.)"),
    ("innate", "tug'ma", "C1", "49", "(adj.) inborn, native, inherent (His incredible athletic talent is innate, he never trains, lifts weights, or practices.)"),
    ("innocuous", "beozor, zararsiz", "C1", "49", "(adj.) harmless, inoffensive (In spite of their innocuous appearance, these mushrooms are actually quite poisonous.)"),
    ("innuendo", "kesatiq, piching (bilvosita)", "C1", "49", "(n.) an insinuation (During the debate, the politician made several innuendos about the sexual activities of his opponent.)"),
    ("inoculate", "emlash qilmoq, vaksina qilmoq", "C1", "49", "(v.) to introduce a microorganism, serum, or vaccine into an organism in order to increase immunity to illness; to vaccinate (I’ve feared needles ever since I was inoculated against 37 diseases at age one; but I have also never been sick.)"),
    ("inquisitor", "so'roqchi, tergovchi (shafqatsiz)", "C1", "49", "(n.) one who inquires, especially in a hostile manner (The inquisitor was instructed to knock on every door in town in order to find the fugitive.)"),
    ("insatiable", "to'ymas, qonmas", "C1", "49", "(adj.) incapable of being satisfied (My insatiable appetite for melons can be a real problem in the winter.)"),
    ("insipid", "bemaza, ruhsiz", "C1", "49", "(adj.) dull, boring (The play was so insipid, I fell asleep halfway through.)"),
    ("insolent", "beadab, gustoh", "C1", "49", "(adj.) rude, arrogant, overbearing (That celebrity is so insolent, making fun of his fans right to their faces.)"),
    ("insular", "biqiq, tor dunyoqarashli", "C1", "49", "(adj.) separated and narrow-minded; tight-knit, closed off (Because of the sensitive nature of their jobs, those who work for the CIA must remain insular and generally only spend time with each other.)"),
    ("insinuate", "shama qilmoq, piching bilan bildirmoq", "C1", "49", "(v.) to suggest indirectly or subtly (I wish Luke and Spencer would stop insinuating that my perfect report card is the result of anything other than my superior intelligence and good work habits.)"),
    ("insurgent", "isyonchi, qo'zg'olonchi", "C1", "49", "(n.) one who rebels (The insurgent snuck into and defaced a different classroom each night until the administration agreed to meet his demands.)"),
    ("interject", "gap qo'shmoq, luqma tashlamoq", "C1", "49", "(v.) to insert between other things (During our conversation, the cab driver occasionally interjected his opinion.)"),
    ("interlocutor", "suhbatdosh", "C1", "49", "(n.) someone who participates in a dialogue or conversation (When the officials could not come to an agreement over the correct cover of the flags, the prime minister acted as an interlocutor.)"),
    ("interminable", "tugamas, cheksiz cho'zilgan", "C1", "49", "(adj.) without possibility of end (The fact that biology lectures came just before lunch made them seem interminable.)"),
    ("intimation", "shama, ishora", "C1", "49", "(n.) an indirect suggestion (Mr. Brinford’s intimation that he would soon pass away occurred when he began to discuss how to distribute his belongings among his children.)"),
    ("intractable", "gapga kirmas, boshqarib bo'lmas", "C1", "49", "(adj.) difficult to manipulate, unmanageable (There was no end in sight to the intractable conflict between the warring countries.)"),
    ("intransigent", "murosasiz, qaysar", "C1", "49", "(adj.) refusing to compromise, often on an extreme opinion (The intransigent child said he would have 12 scoops of ice cream, or he would bang his head against the wall until his mother fainted from fear.)"),
    ("intrepid", "qo'rqmas, dovyurak", "C1", "49", "(adj.) brave in the face of danger (After scaling a live volcano prior to its eruption, the explorer was praised for his intrepid attitude.)"),
    ("inundate", "suv bosmoq; ko'mib tashlamoq (ish bilan)", "C1", "49", "(v.) to flood with abundance (Because I am the star of a new sitcom, my fans are sure to inundate me with fan mail and praise.)"),
    ("inure", "ko'niktirmoq, chiniqtirmoq", "C1", "49", "(v.) to cause someone or something to become accustomed to a situation (Twenty years in the salt mines inured the man to the discomforts of dirt and grime.)"),
    ("invective", "haqoratli so'zlar, dashnom", "C1", "49", "(n.) an angry verbal attack (My mother’s irrational invective against the way I dress only made me decide to dye my hair green.)"),
    # ---- Unit 50 (C1) ----
    ("inveterate", "ashaddiy, odat qilib olgan", "C1", "50", "(adj.) stubbornly established by habit (I’m the first to admit that I’m an inveterate coffee drinker—I drink four cups a day.)"),
    ("inviolable", "daxlsiz, buzib bo'lmas", "C1", "50", "(adj.) secure from assault (Nobody was ever able to break into Batman’s inviolable Batcave.)"),
    ("irascible", "jizzaki, tez achchig'lanadigan", "C1", "50", "(adj.) easily angered (At the smallest provocation, my irascible cat will begin scratching and clawing.)"),
    ("iridescent", "kamalak ranglarida tovlanuvchi", "C1", "50", "(adj.) showing rainbow colors (The bride’s large diamond ring was iridescent in the afternoon sun.)"),
    ("irreverence", "hurmatsizlik, beodoblik", "C1", "50", "(n.) disrespect (The irreverence displayed by the band that marched through the chapel disturbed many churchgoers.)"),
    ("irrevocable", "qaytarib bo'lmas, uzil-kesil", "C1", "50", "(adj.) incapable of being taken back (The Bill of Rights is an irrevocable part of American law.)"),
    ("jubilant", "shod-xurram, tantana qiluvchi", "C1", "50", "(adj.) extremely joyful, happy (The crowd was jubilant when the firefighter carried the woman from the flaming building.)"),
    ("judicious", "mulohazali, oqilona", "C1", "50", "(adj.) having or exercising sound judgment (When the judicious king decided to compromise rather than send his army to its certain death, he was applauded.)"),
    ("juxtaposition", "yonma-yon qo'yish, qiyoslash", "C1", "50", "(n.) the act of placing two things next to each other for implicit comparison (The interior designer admired my juxtaposition of the yellow couch and green table.)"),
    ("knell", "motam qo'ng'irog'i, halokat darakchisi", "C1", "50", "(n.) the solemn sound of a bell, often indicating a death (Echoing throughout our village, the funeral knell made the stormy day even more grim.)"),
    ("kudos", "olqish, e'tirof", "C1", "50", "(n.) praise for an achievement (After the performance, the reviewers gave the opera singer kudos for a job well done.)"),
    ("laconic", "kamgap, qisqa so'zli", "C1", "50", "(adj.) terse in speech or writing (The author’s laconic style has won him many followers who dislike wordiness.)"),
    ("languid", "lanj, bo'shashgan", "C1", "50", "(adj.) sluggish from fatigue or weakness (In the summer months, the great heat makes people languid and lazy.)"),
    ("larceny", "o'g'rilik", "C1", "50", "(n.) obtaining another’s property by theft or trickery (When my car was not where I had left it, I realized that I was a victim of larceny.)"),
    ("largess", "saxiylik, qo'li ochiqlik", "C1", "50", "(n.) the generous giving of lavish gifts (My boss demonstrated great largess by giving me a new car.)"),
    ("laceration", "chuqur yara, yirtilish", "C1", "50", "(n.) a cut, tear (Because he fell off his bike into a rosebush, the paperboy’s skin was covered with lacerations.)"),
    ("latent", "yashirin, hali namoyon bo'lmagan", "C1", "50", "(adj.) hidden, but capable of being exposed (Sigmund’s dream represented his latent paranoid obsession with other people’s shoes.)"),
    ("laudatory", "maqtovli, olqishlovchi", "C1", "50", "(adj.) expressing admiration or praise (Such laudatory comments are unusual from someone who is usually so reserved in his opinions.)"),
    ("lavish", "saxiylarcha mo'l; sovurmoq", "C1", "50", "1. (adj.) given without limits (Because they had worked very hard, the performers appreciated the critic’s lavish praise.) 2. (v.) to give without limits (Because the performers had worked hard, they deserved the praise that the critic lavished on them.)"),
    ("legerdemain", "qo'l chaqqonligi, ko'zbo'yamachilik", "C1", "50", "(n.) deception, slight-of-hand (Smuggling the French plants through customs by claiming that they were fake was a remarkable bit of legerdemain.)"),
    ("lenient", "yumshoq, kechirimli", "C1", "50", "(adj.) demonstrating tolerance or gentleness (Because Professor Oglethorpe allowed his students to choose their final grades, the other teachers believed that he was excessively lenient.)"),
    ("lethargic", "lanj, karaxt", "C1", "50", "(adj.) in a state of sluggishness or apathy (When Jean Claude explained to his boss that he was lethargic and didn’t feel like working that day, the boss fired him.)"),
    ("liability", "javobgarlik; yuk bo'luvchi narsa", "C1", "50", "1. (n.) something for which one is legally responsible, usually involving a disadvantage or risk (The bungee-jumping tower was a great liability for the owners of the carnival.) 2. (n.) a handicap, burden (Because she often lost her concentration and didn’t play defense, Marcy was a liability to the team.)"),
    ("libertarian", "erkinlik tarafdori", "C1", "50", "(adj.) advocating principles of liberty and free will (The dissatisfied subjects overthrew the monarch and replaced him with a libertarian ruler who respected their democratic principles.)"),
    ("licentious", "axloqsiz, buzuq", "C1", "50", "(adj.) displaying a lack of moral or legal restraints (Marilee has always been fascinated by the licentious private lives of politicians.)"),
    ("limpid", "tiniq, zilol", "C1", "50", "(adj.) clear, transparent (Mr. Johnson’s limpid writing style greatly pleased readers who disliked complicated novels.)"),
    ("linchpin", "tayanch nuqta, asosiy bo'g'in", "C1", "50", "(n.) something that holds separate parts together (The linchpin in the prosecution’s case was the hair from the defendant’s head, which was found at the scene of the crime.)"),
    ("lithe", "egiluvchan, chayir", "C1", "50", "(adj.) graceful, flexible, supple (Although the dancers were all outstanding, Jae Sun’s control of her lithe body was particularly impressive.)"),
    ("litigant", "sudlashuvchi tomon, da'vogar", "C1", "50", "(n.) someone engaged in a lawsuit (When the litigants began screaming at each other, Judge Koch ordered them to be silent.)"),
    ("lucid", "ravshan, tushunarli; hushyor", "C1", "50", "(adj.) clear, easily understandable (Because Guenevere’s essay was so lucid, I only had to read it once to understand her reasoning.)"),
    ("luminous", "nurli, yorug'", "C1", "50", "(adj.) brightly shining (The light of the luminous moon graced the shoulders of the beautiful maiden.)"),
    ("lurid", "vahimali, qonli-tafsilotli", "C1", "50", "(adj.) ghastly, sensational (Gideon’s story, in which he described a character torturing his sister’s dolls, was judged too lurid to be printed in the school’s literary magazine.)"),
    ("maelstrom", "girdob, to'polon", "C1", "50", "(n.) a destructive whirlpool which rapidly sucks in objects (Little did the explorers know that as they turned the next bend of the calm river a vicious maelstrom would catch their boat.)"),
    ("magnanimous", "olijanob, bag'rikeng", "C1", "50", "(adj.) noble, generous (Although I had already broken most of her dishes, Jacqueline was magnanimous enough to continue letting me use them.)"),
    ("malediction", "la'nat, qarg'ish", "C1", "50", "(n.) a curse (When I was arrested for speeding, I screamed maledictions against the policeman and the entire police department.)"),
    ("malevolent", "yovuz niyatli, badxoh", "C1", "50", "(adj.) wanting harm to befall others (The malevolent old man sat in the park all day, tripping unsuspecting passersby with his cane.)"),
    ("malleable", "egiluvchan, ta'sirga beriluvchan", "C1", "50", "(adj.) capable of being shaped or transformed (Maximillian’s political opinions were so malleable that anyone he talked to was able to change his mind instantly.)"),
    ("mandate", "vakolat, topshiriq; buyurmoq", "C1", "50", "(n.) an authoritative command (In the Old Testament, God mandates that no one should steal.)"),
    ("manifold", "xilma-xil, ko'p qirrali", "C1", "50", "(adj.) diverse, varied (The popularity of Dante’s Inferno is partly due to the fact that the work allows for manifold interpretations.)"),
    ("maudlin", "yig'loqi, ortiqcha hissiyotli", "C1", "50", "(adj.) weakly sentimental (Although many people enjoy romantic comedies, I usually find them maudlin and shallow.)"),
    # ---- Unit 51 (C1) ----
    ("maverick", "o'z yo'lidan yuruvchi, isyonkor mustaqil", "C1", "51", "(n.) an independent, nonconformist person (Andreas is a real maverick and always does things his own way.)"),
    ("manifest", "yaqqol ko'rinib turgan; namoyon qilmoq", "C1", "51", "1. (adj.) easily understandable, obvious (When I wrote the wrong sum on the chalkboard, my mistake was so manifest that the entire class burst into laughter.) 2. (v.) to show plainly (His illness first manifested itself with particularly violent hiccups.)"),
    ("mawkish", "soxta-hissiyotli, me'daga tegadigan", "C1", "51", "(adj.) characterized by sick sentimentality (Although some nineteenthcentury critics viewed Dickens’s writing as mawkish, contemporary readers have found great emotional depth in his works.)"),
    ("maxim", "hikmatli so'z, maqol", "C1", "51", "(n.) a common saying expressing a principle of conduct (Miss Manners’s etiquette maxims are both entertaining and instructional.)"),
    ("meager", "ozgina, arzimas", "C1", "51", "(adj.) deficient in size or quality (My meager portion of food did nothing to satisfy my appetite.)"),
    ("medley", "aralashma, xilma-xil to'plam", "C1", "51", "(n.) a mixture of differing things (Susannah’s wardrobe contained an astonishing medley of colors, from olive green to fluorescent pink.)"),
    ("mendacious", "yolg'onchi, aldamchi", "C1", "51", "(adj.) having a lying, false character (The mendacious content of the tabloid magazines is at least entertaining.)"),
    ("mercurial", "kayfiyati tez o'zgaruvchan", "C1", "51", "(adj.) characterized by rapid change or temperamentality (Though he was widely respected for his mathematical proofs, the mercurial genius was impossible to live with.)"),
    ("meritorious", "maqtovga loyiq, xizmat ko'rsatgan", "C1", "51", "(adj.) worthy of esteem or reward (Manfred was given the congressional medal of honor for his meritorious actions.)"),
    ("metamorphosis", "butunlay o'zgarish, evrilish", "C1", "51", "(n.) the change of form, shape, substance (Winnifred went to the gym every day for a year and underwent a metamorphosis from a waiflike girl to an athletic woman.)"),
    ("meticulous", "sinchkov, ipidan ignasigacha puxta", "C1", "51", "(adj.) extremely careful with details (The ornate needlework in the bride’s gown was a product of meticulous handiwork.)"),
    ("mitigate", "yumshatmoq, kamaytirmoq", "C1", "51", "(v.) to make less violent, alleviate (When I had an awful sore throat, only warm tea would mitigate the pain.)"),
    ("moderate", "me'yordagi, o'rtacha; yumshatmoq", "C1", "51", "1. (adj.) not extreme (Luckily, the restaurant we chose had moderate prices; none of us have any money.) 2. (n.) one who expresses moderate opinions (Because he found both the liberal and conservative proposals too excessive, Mr. Park sided with the moderates.)"),
    ("modicum", "ozgina miqdor, zarra", "C1", "51", "(n.) a small amount of something (Refusing to display even a modicum of sensitivity, Henrietta announced her boss’s affair in front of the entire office.)"),
    ("modulate", "ohangini o'zgartirmoq, moslamoq", "C1", "51", "(v.) to pass from one state to another, especially in music (The composer wrote a piece that modulated between minor and major keys.)"),
    ("mollify", "tinchlantirmoq, yumshatmoq", "C1", "51", "(v.) to soften in temper (The police officer mollified the angry woman by giving her a warning instead of a ticket.)"),
    ("morass", "botqoq; chigal ahvol", "C1", "51", "(n.) a wet swampy bog; figuratively, something that traps and confuses (When Theresa lost her job, she could not get out of her financial morass.)"),
    ("mores", "urf-odatlar, axloq me'yorlari", "C1", "51", "(n.) the moral attitudes and fixed customs of a group of people. (Mores change over time; many things that were tolerated in 1975 are no longer seen as being socially acceptable.)"),
    ("morose", "ma'yus, xo'mraygan", "C1", "51", "(adj.) gloomy or sullen (Jason’s morose nature made him very unpleasant to talk to.)"),
    ("multifarious", "serqirra, turli-tuman", "C1", "51", "(adj.) having great diversity or variety (This Swiss Army knife has multifarious functions and capabilities. Among other things, it can act as a knife, a saw, a toothpick, and a slingshot.)"),
    ("munificence", "saxovat, qo'li ochiqlik", "C1", "51", "(n.) generosity in giving (The royal family’s munificence made everyone else in their country rich.)"),
    ("mutable", "o'zgaruvchan", "C1", "51", "(adj.) able to change (Because fashion is so mutable, what is trendy today will look outdated in five years.)"),
    ("myriad", "son-sanoqsiz, behisob", "C1", "51", "(adj.) consisting of a very great number (It was difficult to decide what to do Friday night because the city presented us with myriad possibilities for fun.)"),
    ("nadir", "eng tuban nuqta, tubanlik", "C1", "51", "(n.) the lowest point of something (My day was boring, but the nadir came when I accidentally spilled a bowl of spaghetti on my head.)"),
    ("nebulous", "mavhum, tumanli", "C1", "51", "(adj.) vaguely defined, cloudy (The transition between governments meant that who was actually in charge was a nebulous matter.)"),
    ("nefarious", "yovuz, qabih", "C1", "51", "(adj.) heinously villainous (Although Dr. Meanman’s nefarious plot to melt the polar icecaps was terrifying, it was so impractical that nobody really worried about it.)"),
    ("negligent", "beparvo, e'tiborsiz", "C1", "51", "(adj.) habitually careless, neglectful (Jessie’s grandfather called me a negligent fool after I left the door to his apartment unlocked even though there had been a recent string of robberies.)"),
    ("nascent", "endi tug'ilayotgan, kurtak holidagi", "C1", "51", "(adj.) in the process of being born or coming into existence (Unfortunately, my brilliant paper was only in its nascent form on the morning that it was due.)"),
    ("neophyte", "yangi boshlovchi, shogird", "C1", "51", "(n.) someone who is young or inexperienced (As a neophyte in the literary world, Malik had trouble finding a publisher for his first novel.)"),
    ("nocturnal", "tungi, kechasi faol", "C1", "51", "(adj.) relating to or occurring during the night (Jackie was a nocturnal person; she would study until dawn and sleep until the evening.)"),
    ("noisome", "badbo'y, jirkanch", "C1", "51", "(adj.) unpleasant, offensive, especially to the sense of smell (Nobody would enter the stalls until the horse’s noisome leavings were taken away.)"),
    ("nomadic", "ko'chmanchi", "C1", "51", "(adj.) wandering from place to place (In the first six months after college, Jose led a nomadic life, living in New York, California, and Idaho.)"),
    ("nominal", "nomigagina, arzimas", "C1", "51", "(adj.) trifling, insignificant (Because he was moving the following week and needed to get rid of his furniture more than he needed money, Jordan sold everything for a nominal fee.)"),
    ("nonchalant", "beparvo, sovuqqon", "C1", "51", "(adj.) having a lack of concern, indifference (Although deep down she was very angry, Marsha acted in a nonchalant manner when she found out that her best friend had used her clothing without asking.)"),
    ("nondescript", "ko'zga tashlanmaydigan, oddiy", "C1", "51", "(adj.) lacking a distinctive character (I was surprised when I saw the movie star in person because she looked nondescript.)"),
    ("novice", "yangi boshlovchi, tajribasiz", "C1", "51", "(n.) a beginner, someone without training or experience (Because we were all novices at yoga, our instructor decided to begin with the basics.)"),
    ("noxious", "zaharli, zararli", "C1", "51", "(adj.) harmful, unwholesome (Environmentalists showed that the noxious weeds were destroying the insects’ natural habitats.)"),
    ("nuance", "nozik farq, ohang", "C1", "51", "(n.) a slight variation in meaning, tone, expression (The nuances of the poem were not obvious to the casual reader, but the professor was able to point them out.)"),
    # ---- Unit 52 (C1) ----
    ("obdurate", "toshbag'ir qaysar, yumshamas", "C1", "52", "(adj.) unyielding to persuasion or moral influences (The obdurate old man refused to take pity on the kittens.)"),
    ("obfuscate", "ataylab chalkashtirmoq, xiralashtirmoq", "C1", "52", "(v.) to render incomprehensible (The detective did want to answer the newspaperman’s questions, so he obfuscated the truth.)"),
    ("oblique", "qiya; aylanma, bilvosita", "C1", "52", "(adj.) diverging from a straight line or course, not straightforward (Martin’s oblique language confused those who listened to him.)"),
    ("oblivious", "parvosiz, sezmaydigan", "C1", "52", "(adj.) lacking consciousness or awareness of something (Oblivious to the burning smell emanating from the kitchen, my father did not notice that the rolls in the oven were burned until much too late.)"),
    ("obscure", "noma'lum, xira; yashirmoq", "C1", "52", "(adj.) unclear, partially hidden (Because he was standing in the shadows, his features were obscure.)"),
    ("obsequious", "laganbardor, xushomadgo'y", "C1", "52", "(adj.) excessively compliant or submissive (Mark acted like Janet’s servant, obeying her every request in an obsequious manner.)"),
    ("obstinate", "qaysar, o'jar", "C1", "52", "(adj.) not yielding easily, stubborn (The obstinate child refused to leave the store until his mother bought him a candy bar.)"),
    ("obstreperous", "sershovqin, itoatsiz", "C1", "52", "(adj.) noisy, unruly (Billy’s obstreperous behavior prompted the librarian to ask him to leave the reading room.)"),
    ("obtuse", "zehni past, farosatsiz", "C1", "52", "(adj.) lacking quickness of sensibility or intellect (Political opponents warned that the prime minister’s obtuse approach to foreign policy would embroil the nation in mindless war.)"),
    ("odious", "jirkanch, yomon ko'rilgan", "C1", "52", "(adj.) instilling hatred or intense displeasure (Mark was assigned the odious task of cleaning the cat’s litter box.)"),
    ("ominous", "xosiyatsiz, xavf soluvchi", "C1", "52", "(adj.) foreboding or foreshadowing evil (The fortuneteller’s ominous words flashed through my mind as the hooded figure approached me in the alley.)"),
    ("onerous", "og'ir, mashaqqatli", "C1", "52", "(adj.) burdensome (My parents lamented that the pleasures of living in a beautiful country estate no longer outweighed the onerous mortgage payments.)"),
    ("opulent", "hashamatli, badavlat", "C1", "52", "(adj.) characterized by rich abundance verging on ostentation (The opulent furnishings of the dictator’s private compound contrasted harshly with the meager accommodations of her subjects.)"),
    ("officious", "o'z ishini bilib o'zgalarga aralashuvchi, xizmatkash", "C1", "52", "(adj.) offering one’s services when they are neither wanted nor needed (Brenda resented Allan’s officious behavior when he selected colors that might best improve her artwork.)"),
    ("oration", "tantanali nutq", "C1", "52", "(n.) a speech delivered in a formal or ceremonious manner (The prime minister was visibly shaken when the unruly parliament interrupted his oration about failed domestic policies.)"),
    ("ornate", "serbezak, hashamdor", "C1", "52", "(adj.) highly elaborate, excessively decorated (The ornate styling of the new model of luxury car could not compensate for the poor quality of its motor.)"),
    ("oscillate", "tebranmoq, u yoqdan-bu yoqqa o'zgarmoq", "C1", "52", "(v.) to sway from one side to the other (My uncle oscillated between buying a station wagon to transport his family and buying a sports car to satisfy his boyhood fantasies.)"),
    ("ostensible", "ko'rinishdagi, go'yoki", "C1", "52", "(adj.) appearing as such, seemingly (Jack’s ostensible reason for driving was that airfare was too expensive, but in reality, he was afraid of flying.)"),
    ("ostentatious", "ko'z-ko'z qilingan, manman", "C1", "52", "(adj.) excessively showy, glitzy (On the palace tour, the guide focused on the ostentatious decorations and spoke little of the royal family’s history.)"),
    ("ostracism", "jamiyatdan chetlatish, badarg'a", "C1", "52", "(n.) exclusion from a group (Beth risked ostracism if her roommates discovered her flatulence.)"),
    ("pacific", "tinchliksevar, osoyishta", "C1", "52", "(adj.) soothing (The chemistry professor’s pacific demeanor helped the class remain calm after the experiment exploded.)"),
    ("palatable", "yeb bo'ladigan, ma'qul", "C1", "52", "(adj.) agreeable to the taste or sensibilities (Despite the unpleasant smell, the exotic cheese was quite palatable.)"),
    ("palette", "bo'yoqlar taxtasi, rang palitasi", "C1", "52", "(adj.) a range of colors or qualities (The palette of colors utilized in the painting was equaled only by the range of intense emotions the piece evoked.)"),
    ("palliate", "yengillashtirmoq (davolamasdan)", "C1", "52", "(v.) to reduce the severity of (The doctor trusted that the new medication would palliate her patient’s discomfort.)"),
    ("pallid", "rangpar, oqargan", "C1", "52", "(adj.) lacking color (Dr. Van Helsing feared that Lucy’s pallid complexion was due to an unexplained loss of blood.)"),
    ("panacea", "barcha dardga davo, sehrli yechim", "C1", "52", "(n.) a remedy for all ills or difficulties (Doctors wish there was a single panacea for every disease, but sadly there is not.)"),
    ("paragon", "mukammallik namunasi, timsol", "C1", "52", "(n.) a model of excellence or perfection (The mythical Helen of Troy was considered a paragon of female beauty.)"),
    ("paramount", "eng muhim, birinchi darajali", "C1", "52", "(adj.) greatest in importance, rank, character (It was paramount that the bomb squad disconnect the blue wire before removing the fuse.)"),
    ("pariah", "jamiyatdan chiqarilgan kimsa, xo'rlangan", "C1", "52", "(n.) an outcast (Following the discovery of his plagiarism, Professor Hurley was made a pariah in all academic circles.)"),
    ("parody", "kulgili taqlid, parodiya", "C1", "52", "(n.) a satirical imitation (A hush fell over the classroom when the teacher returned to find Deborah acting out a parody of his teaching style.)"),
    ("parsimony", "xasislik, ziqnalik", "C1", "52", "(n.) frugality, stinginess (Many relatives believed that my aunt’s wealth resulted from her parsimony.)"),
    ("partisan", "tarafkash, partiyaviy", "C1", "52", "(n.) a follower, adherent (The king did not believe that his rival could round up enough partisans to overthrow the monarchy.)"),
    ("patent", "yaqqol, ochiq-oydin; patent", "C1", "52", "(adj.) readily seen or understood, clear (The reason for Jim’s abdominal pain was made patent after the doctor performed a sonogram.)"),
    ("pathology", "kasallik tabiati, patologiya", "C1", "52", "(n.) a deviation from the normal (Dr. Hastings had difficulty identifying the precise nature of Brian’s pathology.)"),
    ("pathos", "achinish uyg'otuvchi kuch, hazinlik", "C1", "52", "(n.) an emotion of sympathy (Martha filled with pathos upon discovering the scrawny, shivering kitten at her door.)"),
    # ---- Unit 53 (C1) ----
    ("pejorative", "kamsituvchi, salbiy ma'noli", "C1", "53", "(adj.) derogatory, uncomplimentary (The evening’s headline news covered an international scandal caused by a pejorative statement the famous senator had made in reference to a foreign leader.)"),
    ("pellucid", "shaffof, tiniq", "C1", "53", "(adj.) easily intelligible, clear (Wishing his book to be pellucid to the common man, Albert Camus avoided using complicated grammar when composing The Stranger.)"),
    ("penchant", "moyillik, ishqibozlik", "C1", "53", "(n.) a tendency, partiality, preference (Jill’s dinner parties quickly became monotonous on account of her penchant for Mexican dishes.)"),
    ("penitent", "pushaymon, tavba qiluvchi", "C1", "53", "(adj.) remorseful, regretful (The jury’s verdict may have been more lenient if the criminal had appeared penitent for his gruesome crimes.)"),
    ("paucity", "kamlik, taqchillik", "C1", "53", "(adj.) small in quantity (Gilbert lamented the paucity of twentieth century literature courses available at the college.)"),
    ("penultimate", "oxirgisidan oldingi", "C1", "53", "(adj.) next to last (Having smoked the penultimate cigarette remaining in the pack, Cybil discarded the last cigarette and resolved to quit smoking.)"),
    ("penurious", "o'ta qashshoq; xasis", "C1", "53", "(adj.) miserly, stingy (Stella complained that her husband’s penurious ways made it impossible to live the lifestyle she felt she deserved.)"),
    ("perfidious", "xoin, vafosiz", "C1", "53", "(adj.) disloyal, unfaithful (After the official was caught selling government secrets to enemy agents, he was executed for his perfidious ways.)"),
    ("perfunctory", "yuzaki, majburan qilingan", "C1", "53", "(adj.) showing little interest or enthusiasm (The radio broadcaster announced the news of the massacre in a surprisingly perfunctory manner.)"),
    ("permeate", "singib o'tmoq, qamrab olmoq", "C1", "53", "(v.) to spread throughout, saturate (Mrs. Huxtable was annoyed that the wet dog’s odor had permeated the furniture’s upholstery.)"),
    ("pernicious", "halokatli, zararli", "C1", "53", "(adj.) extremely destructive or harmful (The new government feared that the Communist sympathizers would have a pernicious influence on the nation’s stability.)"),
    ("perplex", "boshini qotirmoq, hayron qoldirmoq", "C1", "53", "(v.) to confuse (Brad was perplexed by his girlfriend’s suddenly distant manner.)"),
    ("perspicacity", "o'tkir zehn, sinchkovlik", "C1", "53", "(adj.) shrewdness, perceptiveness (The detective was too humble to acknowledge that his perspicacity was the reason for his professional success.)"),
    ("pert", "sho'x, betakalluf", "C1", "53", "(adj.) flippant, bold (My parents forgave Sandra’s pert humor at the dinner table because it had been so long since they had last seen her.)"),
    ("pertinacious", "qat'iyatli, o'jarlik bilan yopishib oluvchi", "C1", "53", "(adj.) stubbornly persistent (Harry’s parents were frustrated with his pertinacious insistence that a monster lived in his closet. Then they opened the closet door and were eaten.)"),
    ("perusal", "sinchiklab o'qib chiqish", "C1", "53", "(n.) a careful examination, review (The actor agreed to accept the role after a two-month perusal of the movie script.)"),
    ("pervasive", "hamma yoqni qamrab olgan, keng tarqalgan", "C1", "53", "(adj.) having the tendency to spread throughout (Stepping off the plane in Havana, I recognized the pervasive odor of sugar cane fields on fire.)"),
    ("petulance", "injiqlik, arazchilik", "C1", "53", "(n.) rudeness, irritability (The Nanny resigned after she could no longer tolerate the child’s petulance.)"),
    ("philanthropic", "xayriyachi, insonparvar", "C1", "53", "(adj.) charitable, giving (Many people felt that the billionaire’s decision to donate her fortune to house the homeless was the ultimate philanthropic act.)"),
    ("phlegmatic", "sovuqqon, beparvo mizojli", "C1", "53", "(adj.) uninterested, unresponsive (Monique feared her dog was ill after the animal’s phlegmatic response to his favorite chew toy.)"),
    ("pillage", "talamoq, talon-taroj qilmoq", "C1", "53", "(v.) to seize or plunder, especially in war (Invading enemy soldiers pillaged the homes scattered along the country’s border.)"),
    ("pinnacle", "eng yuqori cho'qqi", "C1", "53", "(n.) the highest point (Book reviewers declared that the author’s new novel was extraordinary and probably the pinnacle of Western literature.)"),
    ("pithy", "lo'nda va mazmundor", "C1", "53", "(adj.) concisely meaningful (My father’s long-winded explanation was a stark contrast to his usually pithy statements.)"),
    ("pittance", "arzimas haq, chaqa", "C1", "53", "(n.) a very small amount, especially relating to money (Josh complained that he was paid a pittance for the great amount of work he did at the firm.)"),
    ("placate", "tinchlantirmoq, ko'nglini olmoq", "C1", "53", "(v.) to ease the anger of, soothe (The man purchased a lollipop to placate his irritable son.)"),
    ("placid", "sokin, osoyishta", "C1", "53", "(adj.) calm, peaceful (The placid lake surface was as smooth as glass.)"),
    ("platitude", "siyqa gap, quruq nasihat", "C1", "53", "(n.) an uninspired remark, cliché (After reading over her paper, Helene concluded that what she thought were profound insights were actually just platitudes.)"),
    ("plaudits", "olqishlar, qarsaklar", "C1", "53", "(n.) enthusiastic approval, applause (The controversial new film received plaudits from even the harshest critics.)"),
    ("plausible", "ishonarli, haqiqatga o'xshash", "C1", "53", "(adj.) believable, reasonable (He studied all the data and then came up with a plausible theory that took all factors into account.)"),
    ("plenitude", "mo'l-ko'llik, to'kinlik", "C1", "53", "(n.) an abundance (My grandmother was overwhelmed by the plenitude of tomatoes her garden yielded this season.)"),
    ("pliable", "egiluvchan, ko'ndirsa bo'ladigan", "C1", "53", "(adj.) flexible (Aircraft wings are designed to be somewhat pliable so they do not break in heavy turbulence.)"),
    ("poignant", "yurakni ezuvchi, ta'sirli", "C1", "53", "(adj.) deeply affecting, moving (My teacher actually cried after reading to us the poignant final chapter of the novel.)"),
    ("polemic", "keskin bahs, munozara", "C1", "53", "(n.) an aggressive argument against a specific opinion (My brother launched into a polemic against my arguments that capitalism was an unjust economic system.)"),
    ("portent", "yomon alomat, darak", "C1", "53", "(n.) an omen (When a black cat crossed my sister’s path while she was walking to school, she took it as a portent that she would do badly on her spelling test.)"),
    ("plethora", "ortiqcha ko'plik, serobgarchilik", "C1", "53", "(n.) an abundance, excess (The wedding banquet included a plethora of oysters piled almost three feet high.)"),
    ("potable", "ichishga yaroqli", "C1", "53", "(adj.) suitable for drinking (During sea voyages it is essential that ships carry a supply of potable water because salty ocean water makes anyone who drinks it sick.)"),
    ("potentate", "hukmdor, qudratli shaxs", "C1", "53", "(n.) one who has great power, a ruler (All the villagers stood along the town’s main road to observe as the potentate’s procession headed towards the capital.)"),
    ("pragmatic", "amaliyotchi, hisob-kitobli", "C1", "53", "(adj.) practical (The politician argued that while increased security measures might not fit with the lofty ideals of the nation, they were a pragmatic necessity to ensure everyone’s safety.)"),
    ("preclude", "imkonini yo'q qilmoq, oldini olmoq", "C1", "53", "(v.) to prevent (My grandfather’s large and vicious guard dog precluded anyone from entering the yard.)"),
    # ---- Unit 54 (C1) ----
    ("precocious", "yoshiga nisbatan erta rivojlangan", "C1", "54", "(adj.) advanced, developing ahead of time (Derek was so academically precocious that by the time he was 10 years old, he was already in the ninth grade.)"),
    ("predilection", "moyillik, xush ko'rish", "C1", "54", "(n.) a preference or inclination for something (Francois has a predilection for eating scrambled eggs with ketchup, though I prefer to eat eggs without any condiments.)"),
    ("preponderance", "ustunlik, ko'pchilikni tashkil etish", "C1", "54", "(adj.) superiority in importance or quantity (Britain’s preponderance of naval might secured the nation’s role as a military power.)"),
    ("prepossessing", "yoqimtoy, o'ziga tortadigan", "C1", "54", "(adj.) occupying the mind to the exclusion of other thoughts or feelings (His prepossessing appearance made it impossible for me to think of anything else.)"),
    ("presage", "darak bermoq, bashorat qilmoq", "C1", "54", "(n.) an omen (When my uncle’s old war injury ached, he interpreted it as a presage of bad weather approaching.)"),
    ("prescient", "oldindan ko'ra biluvchi", "C1", "54", "(adj.) to have foreknowledge of events (Questioning the fortune cookie’s prediction, Ray went in search of the old hermit who was rumored to be prescient.)"),
    ("presumptuous", "haddidan oshgan, o'ziga bino qo'ygan", "C1", "54", "(adj.) disrespectfully bold (The princess grew angry after the presumptuous noble tried to kiss her, even though he was far below her in social status.)"),
    ("pretense", "bahona, soxta ko'rinish", "C1", "54", "(n.)an appearance or action intended to deceive (Though he actually wanted to use his parents’ car to go on a date, Nick borrowed his parents’ car under the pretense of attending a group study session.)"),
    ("privation", "muhtojlik, yo'qchilik", "C1", "54", "(n.) lacking basic necessities (After decades of rule by an oppressive government that saw nothing wrong with stealing from its citizens, the recent drought only increased the people’s privation.)"),
    ("probity", "halollik, pokdomonlik", "C1", "54", "(n.) virtue, integrity (Because he was never viewed as a man of great probity, no one was surprised by Mr. Samson’s immoral behavior.)"),
    ("proclivity", "moyillik, intilish", "C1", "54", "(n.) a strong inclination toward something (In a sick twist of fate, Harold’s childhood proclivity for torturing small animals grew into a desire to become a surgeon.)"),
    ("procure", "topib olmoq, qo'lga kiritmoq", "C1", "54", "(v.) to obtain, acquire (The FBI was unable to procure sufficient evidence to charge the gangster with racketeering.)"),
    ("profane", "muqaddasotga hurmatsiz; so'kinmoq", "C1", "54", "(adj.) lewd, indecent (Jacob’s profane act of dumping frogs in the holy water in the chapel at his boarding school resulted in his dismissal.)"),
    ("profligate", "isrofgar, buzuq", "C1", "54", "(adj.) dissolute, extravagant (The profligate gambler loved to drink, spend money, steal, cheat, and hang out with prostitutes.)"),
    ("profuse", "mo'l, serob", "C1", "54", "(adj.) plentiful, abundant (The fans were profuse in their cheers for the star basketball player.)"),
    ("propagate", "ko'paytirmoq, yoymoq", "C1", "54", "(v.) to multiply, spread out (Rumors of Paul McCartney’s demise propagated like wildfire throughout the world.)"),
    ("propensity", "moyillik, tabiiy intilish", "C1", "54", "(n.) an inclination, preference (Dermit has a propensity for dangerous activities such as bungee jumping.)"),
    ("propitious", "qulay, xayrli", "C1", "54", "(adj.) favorable (The dark storm clouds visible on the horizon suggested that the weather would not be propitious for sailing.)"),
    ("propriety", "odob-axloq, o'rinlilik", "C1", "54", "(n.) the quality or state of being proper, decent (Erma’s old-fashioned parents believed that her mini-skirt lacked the propriety expected of a “nice” girl.)"),
    ("promulgate", "e'lon qilmoq, joriy etmoq", "C1", "54", "(v.) to proclaim, make known (The film professor promulgated that both in terms of sex appeal and political intrigue, Sean Connery’s James Bond was superior to Roger Moore’s.)"),
    ("prosaic", "jo'n, zerikarli", "C1", "54", "(adj.) plain, lacking liveliness (Heather’s prosaic recital of the poem bored the audience.)"),
    ("proscribe", "taqiqlamoq", "C1", "54", "(v.) to condemn, outlaw (The town council voted to proscribe the sale of alcohol on weekends.)"),
    ("protean", "tez o'zgaruvchan, har qiyofaga kiruvchi", "C1", "54", "(adj.)able to change shape; displaying great variety (Among Nigel’s protean talents was his ability to touch the tip of his nose with his tongue.)"),
    ("prowess", "mahorat, jasorat", "C1", "54", "(n.) extraordinary ability (The musician had never taken a guitar lesson in his life, making his prowess with the instrument even more incredible.)"),
    ("prudence", "ehtiyotkorlik, mulohazakorlik", "C1", "54", "(n.) cautious, circumspect (After losing a fortune in a stock market crash, my father vowed to practice greater prudence in future investments.)"),
    ("prurient", "shahvoniy, beadab qiziquvchan", "C1", "54", "(adj.) eliciting or possessing an extraordinary interest in sex (David’s mother was shocked by the discovery of prurient reading material hidden beneath her son’s mattress.)"),
    ("puerile", "bolalarcha, go'dakcha", "C1", "54", "(adj.) juvenile, immature (The judge demanded order after the lawyer’s puerile attempt to object by stomping his feet on the courtroom floor.)"),
    ("pugnacious", "janjalkash, urishqoq", "C1", "54", "(adj.) quarrelsome, combative (Aaron’s pugnacious nature led him to start several barroom brawls each month.)"),
    ("pulchritude", "go'zallik, husn", "C1", "54", "(n.) physical beauty (Several of Shakespeare’s sonnets explore the pulchritude of a lovely young man.)"),
    ("punctilious", "rasm-rusumga o'ta rioyakor, sinchkov", "C1", "54", "(adj.) eager to follow rules or conventions (Punctilious Bobby, hall monitor extraordinaire, insisted that his peers follow the rules.)"),
    ("pungent", "achchiq, o'tkir (hid, ta'm)", "C1", "54", "(adj.) having a pointed, sharp quality—often used to describe smells (The pungent odor in the classroom made Joseph lose his concentration during the test.)"),
    ("punitive", "jazolovchi, jazo tariqasidagi", "C1", "54", "(adj.) involving punishment (If caught smoking in the boys’ room, the punitive result is immediate expulsion from school.)"),
    ("putrid", "chirigan, sasigan", "C1", "54", "(adj.) rotten, foul (Those rotten eggs smell putrid.)"),
    ("quagmire", "botqoq; chiqib bo'lmas ahvol", "C1", "54", "(n.) a difficult situation (We’d all like to avoid the kind of military quagmire characterized by the Vietnam War.)"),
    ("quaint", "g'alati-yoqimli, eski usuldagi", "C1", "54", "(adj.) charmingly old-fashioned (Hilda was delighted by the quaint bonnets she saw in Amish country.)"),
    ("quandary", "ikkilanish, boshi berk ko'cha", "C1", "54", "(n.) a perplexed, unresolvable state (Carlos found himself in a quandary: should he choose mint chocolate chip or cookie dough?)"),
    ("quell", "bostirmoq, tinchitmoq", "C1", "54", "(v.) to control or diffuse a potentially explosive situation (The skilled leader deftly quelled the rebellion.)"),
    ("querulous", "noliguvchi, arazchi", "C1", "54", "(adj.) whiny, complaining (If deprived of his pacifier, young Brendan becomes querulous.)"),
    # ---- Unit 55 (C1) ----
    ("quixotic", "xayolparast, amalga oshmas orzuli", "C1", "55", "(adj.) idealistic, impractical (Edward entertained a quixotic desire to fall in love at first sight in a laundromat.)"),
    ("quotidian", "kundalik, oddiy", "C1", "55", "(adj.) daily (Ambika’s quotidian routines include drinking two cups of coffee in the morning.)"),
    ("rail", "qattiq norozilik bildirmoq, so'kmoq", "C1", "55", "(v.) to scold, protest (The professor railed against the injustice of the college’s tenure policy.)"),
    ("rancid", "aynigan, taxir (yog')", "C1", "55", "(adj.) having a terrible taste or smell (Rob was double-dog-dared to eat the rancid egg salad sandwich.)"),
    ("rancor", "adovat, gina-kudurat", "C1", "55", "(n.) deep, bitter resentment (When Eileen challenged me to a fight, I could see the rancor in her eyes.)"),
    ("rapport", "o'zaro iliq munosabat, til topishish", "C1", "55", "(n.) mutual understanding and harmony (When Margaret met her paramour, they felt an instant rapport.)"),
    ("rash", "shoshqaloq, o'ylamasdan qilingan; toshma", "C1", "55", "(adj.) hasty, incautious (It’s best to think things over calmly and thoroughly, rather than make rash decisions.)"),
    ("raze", "yer bilan yakson qilmoq, buzib tashlamoq", "C1", "55", "(v.) to demolish, level (The old tenement house was razed to make room for the large chain store.)"),
    ("rebuke", "tanbeh bermoq, koyimoq", "C1", "55", "(v.) to scold, criticize (When the cops showed up at Sarah’s party, they rebuked her for disturbing the peace.)"),
    ("recalcitrant", "itoatsiz, bo'ysunmas", "C1", "55", "(adj.) defiant, unapologetic (Even when scolded, the recalcitrant young girl simply stomped her foot and refused to finish her lima beans.)"),
    ("recapitulate", "qisqacha takrorlamoq, xulosalamoq", "C1", "55", "(v.) to sum up, repeat (Before the final exam, the teacher recapitulated the semester’s material.)"),
    ("raucous", "bo'g'iq-qattiq shovqinli, xirillagan", "C1", "55", "(adj.) loud, boisterous (Sarah’s neighbors called the cops when her house party got too raucous.)"),
    ("reciprocate", "javob qaytarmoq, o'zaro qilmoq", "C1", "55", "(v.) to give in return (When Steve gave Samantha a sweater for Christmas, she reciprocated by giving him a kiss.)"),
    ("reconcile", "yarashtirmoq; muvofiqlashtirmoq", "C1", "55", "1. (v.) to return to harmony (The feuding neighbors finally reconciled when one brought the other a delicious tuna noodle casserole.) 2. (v.) to make consistent with existing ideas (Alou had to reconcile his skepticism about the existence of aliens with the fact that he was looking at a flying saucer.)"),
    ("rectitude", "to'g'rilik, halollik", "C1", "55", "(n.) uprightness, extreme morality (The priest’s rectitude gave him the moral authority to counsel his parishioners.)"),
    ("redoubtable", "qo'rquv va hurmat uyg'otuvchi, zabardast", "C1", "55", "1. (adj.) formidable (The fortress looked redoubtable set against a stormy sky.) 2. (adj.) commanding respect (The audience greeted the redoubtable speaker with a standing ovation.)"),
    ("refract", "sindirmoq (nurni)", "C1", "55", "(v.) to distort, change (The light was refracted as it passed through the prism.)"),
    ("refurbish", "yangilamoq, ta'mirlamoq", "C1", "55", "(v.) to restore, clean up (The dingy old chair, after being refurbished, commanded the handsome price of $200.)"),
    ("refute", "rad etmoq, puchga chiqarmoq", "C1", "55", "(v.) to prove wrong (Maria refuted the president’s argument as she yelled and gesticulated at the TV.)"),
    ("regurgitate", "qaytarib chiqarmoq; o'ylamay takrorlamoq", "C1", "55", "1. (v.) to vomit (Feeling sick, Chuck regurgitated his dinner.) 2. (v.) to throw back exactly (Margaret rushed through the test, regurgitating all of the facts she’d memorized an hour earlier.)"),
    ("relegate", "pastroq o'ringa tushirmoq, chetga surmoq", "C1", "55", "1. (v.) to assign to the proper place (At the astrology conference, Simon was relegated to the Scorpio room.) 2. (v.) to assign to an inferior place (After spilling a drink on a customer’s shirt, the waiter found himself relegated to the least lucrative shift.)"),
    ("relish", "huzur qilib bahra olmoq, xush ko'rmoq", "C1", "55", "(v.) to enjoy (Pete always relished his bedtime snack.)"),
    ("remedial", "tuzatuvchi, davolovchi", "C1", "55", "(adj.) intended to repair gaps in students’ basic knowledge (After his teacher discovered he couldn’t read, Alex was forced to enroll in remedial English.)"),
    ("remiss", "e'tiborsiz, burchiga sovuqqon", "C1", "55", "(adj.) negligent, failing to take care (The burglar gained entrance because the security guard, remiss in his duties, forgot to lock the door.)"),
    ("renovate", "ta'mirlamoq, yangilamoq", "C1", "55", "1. (v.) restore, return to original state (The renovated antique candelabra looked as good as new.) 2. (v.) to enlarge and make prettier, especially a house (After getting renovated, the house was twice as big and much more attractive.)"),
    ("renown", "shon-shuhrat, dong", "C1", "55", "(n.) honor, acclaim (The young writer earned international renown by winning the Pulitzer Prize.)"),
    ("renunciation", "voz kechish, rad etish", "C1", "55", "(n.) to reject (Fiona’s renunciation of red meat resulted in weight loss, but confused those people who thought she’d been a vegetarian for years.)"),
    ("repentant", "pushaymon, tavba qilgan", "C1", "55", "(adj.) penitent, sorry (The repentant Dennis apologized profusely for breaking his mother’s vase.)"),
    ("replete", "to'la, limmo-lim", "C1", "55", "(adj.) full, abundant (The unedited version was replete with naughty words.)"),
    ("repose", "orom, dam olish", "C1", "55", "(v.) to rest, lie down (The cat, after eating an entire can of tuna fish, reposed in the sun and took a long nap.)"),
    ("reprehensible", "qoralashga loyiq, ayblanadigan", "C1", "55", "(adj.) deserving rebuke (Jean’s cruel and reprehensible attempt to dump her boyfriend on his birthday led to tears and recriminations.)"),
    ("reprieve", "jazoni kechiktirish, muhlat", "C1", "55", "(n.) a temporary delay of punishment (Because the governor woke up in a particularly good mood, he granted hundreds of reprieves to prisoners.)"),
    ("reproach", "ta'na qilmoq, ayblamoq", "C1", "55", "(v.) to scold, disapprove (Brian reproached the customer for failing to rewind the video he had rented.)"),
    ("reprobate", "buzuqi, yaramas odam", "C1", "55", "(adj.) evil, unprincipled (The reprobate criminal sat sneering in the cell.)"),
    ("reprove", "tanbeh bermoq, koyimoq", "C1", "55", "(v.) to scold, rebuke (Lara reproved her son for sticking each and every one of his fingers into the strawberry pie.)"),
    ("repulse", "qaytarmoq (hujumni); jirkantirmoq", "C1", "55", "1. (v.) to disgust (Antisocial Annie tried to repulse people by neglecting to brush her teeth.) 2. (v.) to push back (With a deft movement of her wrist and a punch to the stomach, Lacy repulsed Jack’s attempt to kiss her.)"),
    ("reputable", "obro'li, e'tiborli", "C1", "55", "(adj.) of good reputation (After the most reputable critic in the industry gave the novel a glowing review, sales took off.)"),
    ("requisition", "rasmiy talabnoma, musodara", "C1", "55", "(n.) a demand for goods, usually made by an authority (During the war, the government made a requisition of supplies.)"),
    ("rescind", "bekor qilmoq, chaqirib olmoq", "C1", "55", "(v.) to take back, repeal (The company rescinded its offer of employment after discovering that Jane’s resume was full of lies.)"),
    # ---- Unit 56 (C1) ----
    ("repudiate", "rad etmoq, tan olmaslik", "C1", "56", "(v.) to reject, refuse to accept (Kwame made a strong case for an extension of his curfew, but his mother repudiated it with a few biting words.)"),
    ("reservoir", "suv ombori; zaxira", "C1", "56", "1. (n.) reserves, large supply (Igor the Indomitable had quite a reservoir of strengh and could lift ten tons, even after running 700 miles, jumping over three mountains, and swimming across an ocean.) 2. (n.) a body of water used for storing water (After graduation, the more rebellious members of the senior class jumped into the town reservoir used for drinking water.)"),
    ("resilient", "tez tiklanadigan, chidamli", "C1", "56", "(adj.) able to recover from misfortune; able to withstand adversity (The resilient ballplayer quickly recovered from his wrist injury.)"),
    ("resolve", "qaror qilmoq; hal qilmoq; qat'iyat", "C1", "56", "1. (v.) to find a solution (Sarah and Emma resolved their differences and shook hands.) 2. (v.) to firmly decide (Lady Macbeth resolved to whip her husband into shape.)"),
    ("respite", "muhlat, nafas rostlash", "C1", "56", "(n.) a break, rest (Justin left the pub to gain a brief respite from the smoke and noise.)"),
    ("resplendent", "yarqiragan, ko'rkam", "C1", "56", "(adj.) shiny, glowing (The partygoers were resplendent in diamonds and fancy dress.)"),
    ("restitution", "tovon, qaytarib berish", "C1", "56", "(n.) restoration to the rightful owner (Many people feel that descendants of slaves should receive restitution for the sufferings of their ancestors.)"),
    ("restive", "bezovta, tinib-tinchimas", "C1", "56", "(adj.) resistant, stubborn, impatient (The restive audience pelted the band with mud and yelled nasty comments.)"),
    ("retract", "qaytarib olmoq (so'zini), tortmoq", "C1", "56", "(v.) withdraw (As the media worked itself into a frenzy, the publicist hurriedly retracted his client’s sexist statement.)"),
    ("revel", "shodiyona qilmoq; huzurlanmoq", "C1", "56", "(v.) to enjoy intensely (Theodore reveled in his new status as Big Man on Campus.)"),
    ("revere", "chuqur hurmat qilmoq, e'zozlamoq", "C1", "56", "(v.) to esteem, show deference, venerate (The doctor saved countless lives with his combination of expertise and kindness and became universally revered.)"),
    ("revoke", "bekor qilmoq, kuchdan qoldirmoq", "C1", "56", "(v.) to take back (After missing the curfew set by the court for eight nights in a row, Marcel’s freedom of movement was revoked.)"),
    ("rhapsodize", "hayajon bilan maqtab gapirmoq", "C1", "56", "(v.) to engage in excessive enthusiasm (The critic rhapsodized about the movie, calling it an instant classic.)"),
    ("ribald", "beadab, qo'pol hazilli", "C1", "56", "(adj.) coarsely, crudely humorous (While some giggled at the ribald joke involving a parson’s daughter, most sighed and rolled their eyes.)"),
    ("rife", "keng tarqalgan, to'lib-toshgan", "C1", "56", "(adj.) abundant (Surprisingly, the famous novelist’s writing was rife with spelling errors.)"),
    ("ruminate", "chuqur o'ylamoq, mulohaza yuritmoq", "C1", "56", "(v.) to contemplate, reflect (Terry liked to ruminate while sitting on the banks of the river, staring pensively into the water.)"),
    ("ruse", "hiyla, nayrang", "C1", "56", "(n.) a trick (Oliver concocted an elaborate ruse for sneaking out of the house to meet his girlfriend while simultaneously giving his mother the impression that he was asleep in bed.)"),
    ("saccharine", "o'ta shirin, siropdek yoqimtoy (soxta)", "C1", "56", "(adj.) sickeningly sweet (Tom’s saccharine manner, although intended to make him popular, actually repelled his classmates.)"),
    ("sacrosanct", "daxlsiz muqaddas", "C1", "56", "(adj.) holy, something that should not be criticized (In the United States, the Constitution is often thought of as a sacrosanct document.)"),
    ("sagacity", "donolik, uzoqni ko'rish", "C1", "56", "(n.) shrewdness, soundness of perspective (With remarkable sagacity, the wise old man predicted and thwarted his children’s plan to ship him off to a nursing home.)"),
    ("salient", "ko'zga yaqqol tashlanadigan, asosiy", "C1", "56", "(adj.) significant, conspicuous (One of the salient differences between Alison and Nancy is that Alison is a foot taller.)"),
    ("salutation", "salomlashish, tabrik", "C1", "56", "(n.) a greeting (Andrew regularly began letters with the bizarre salutation “Ahoy ahoy.”)"),
    ("salve", "malham; taskin bermoq", "C1", "56", "(n.) a soothing balm (After Tony applied a salve to his brilliant red sunburn, he soon felt a little better.)"),
    ("sanguine", "nekbin, umidvor", "C1", "56", "(adj.) optimistic, cheery (Polly reacted to any bad news with a sanguine smile and the chirpy cry, “When life hands you lemons, make lemonade!”)"),
    ("satiate", "to'ydirmoq, qondirmoq", "C1", "56", "(v.) to satisfy excessively (Satiated after eating far too much turkey and stuffing, Liza lay on the couch watching football and suffering from stomach pains.)"),
    ("scathing", "ayovsiz, achchiq (tanqid)", "C1", "56", "(adj.) sharp, critical, hurtful (Two hours after breaking up with Russell, Suzanne thought of the perfect scathing retort to his accusations.)"),
    ("sanctimonious", "taqvodor ko'rinishga urinuvchi, riyokor", "C1", "56", "(adj.) giving a hypocritical appearance of piety (The sanctimonious Bertrand delivered stern lectures on the Ten Commandments to anyone who would listen, but thought nothing of stealing cars to make some cash on the side.)"),
    ("scintillating", "uchqunlagan, o'tkir zakovatli", "C1", "56", "(adj.) sparkling (The ice skater’s scintillating rhinestone costume nearly blinded the judges.)"),
    ("scrupulous", "vijdonli, mayda-chuydagacha halol", "C1", "56", "(adj.) painstaking, careful (With scrupulous care, Sam cut a snowflake out of white paper.)"),
    ("scurrilous", "haqoratomuz, bo'htonli", "C1", "56", "(adj.) vulgar, coarse (When Bruno heard the scurrilous accusation being made about him, he could not believe it because he always tried to be nice to everyone.)"),
    ("sedentary", "o'troq, kam harakat", "C1", "56", "(adj.) sitting, settled (The sedentary cat did little but loll in the sun.)"),
    ("semaphore", "signal tizimi, semafor", "C1", "56", "(n.) a visual signal (Anne and Diana communicated with a semaphore involving candles and window shades.)"),
    ("seminal", "asos soluvchi, keyingi rivojga urug' qadagan", "C1", "56", "(adj.) original, important, creating a field (Stephen Greenblatt’s essays on Shakespeare proved to be seminal, because they initiated the critical school of New Historicism.)"),
    ("sensual", "shahvoniy, tan lazzatiga oid", "C1", "56", "(adj.) involving sensory gratification, usually related to sex (With a coy smile, the guest on the blind-date show announced that he considered himself a very sensual person.)"),
    ("sensuous", "sezgilarni qondiruvchi, nafis", "C1", "56", "(adj.) involving sensory gratification (Paul found drinking Coke, with all the little bubbles bursting on his tongue, a very sensuous experience.)"),
    ("serendipity", "kutilmagan baxtli tasodif", "C1", "56", "(n.) luck, finding good things without looking for them (In an amazing bit of serendipity, penniless Paula found a $20 bill in the subway station.)"),
    ("serene", "sokin, xotirjam", "C1", "56", "(adj.) calm, untroubled (Louise stood in front of the Mona Lisa, puzzling over the famous woman’s serene smile.)"),
    ("servile", "qulona itoatkor, laganbardor", "C1", "56", "(adj.) subservient (The servile porter crept around the hotel lobby, bowing and quaking before the guests.)"),
    ("sinuous", "ilon izi, egri-bugri", "C1", "56", "(adj.) lithe, serpentine (With the sinuous movements of her arms, the dancer mimicked the motion of a snake.)"),
    # ---- Unit 57 (C1) ----
    ("sobriety", "hushyorlik; vazminlik", "C1", "57", "(n.) sedate, calm (Jason believed that maintaining his sobriety in times of crisis was the key to success in life.)"),
    ("solicitous", "g'amxo'r, kuyunchak", "C1", "57", "(adj.) concerned, attentive (Jim, laid up in bed with a nasty virus, enjoyed the solicitous attentions of his mother, who brought him soup and extra blankets.)"),
    ("solipsistic", "faqat o'zini mavjud deb biluvchi, xudbin", "C1", "57", "(adj.) believing that oneself is all that exists (Colette’s solipsistic attitude completely ignored the plight of the homeless people on the street.)"),
    ("soluble", "eriydigan; hal etsa bo'ladigan", "C1", "57", "(adj.) able to dissolve (The plot of the spy film revolved around an untraceable and water-soluble poison.)"),
    ("solvent", "to'lovga qodir; erituvchi", "C1", "57", "1. (n.) a substance that can dissolve other substances (Water is sometimes called the universal solvent because almost all other substances can dissolve into it.) 2. (adj.) able to pay debts (Upon receiving an unexpected check from her aunt, Annabelle found herself suddenly solvent.)"),
    ("somnolent", "uyqusiragan, mudroq", "C1", "57", "(adj.) sleepy, drowsy (The somnolent student kept falling asleep and waking up with a jerk.)"),
    ("sophomoric", "o'zini bilarmon sanagan, xom", "C1", "57", "(adj.) immature, uninformed (The mature senior rolled her eyes at the sophomoric gross-out humor of the underclassman.)"),
    ("sovereign", "oliy hukmdor; mustaqil", "C1", "57", "(adj.) having absolute authority in a certain realm (The sovereign queen, with steely resolve, ordered that the traitorous nobleman be killed.)"),
    ("speculative", "taxminiy, faraziy", "C1", "57", "(adj.) not based in fact (Sadly, Tessa was convicted on merely speculative evidence.)"),
    ("spurious", "soxta, qalbaki", "C1", "57", "(adj.) false but designed to seem plausible (Using a spurious argument, John convinced the others that he had won the board game on a technicality.)"),
    ("stagnate", "turg'unlashmoq, rivojlanmay qolmoq", "C1", "57", "(v.) to become or remain inactive, not develop, not flow (With no room for advancement, the waiter’s career stagnated.)"),
    ("staid", "vazmin, jiddiy", "C1", "57", "(adj.) sedate, serious, self-restrained (The staid butler never changed his expression no matter what happened.)"),
    ("stingy", "xasis, ziqna", "C1", "57", "(adj.) not generous, not inclined to spend or give (Scrooge’s stingy habits did not fit with the generous, giving spirit of Christmas.)"),
    ("stolid", "hissiz, befarq", "C1", "57", "(adj.) expressing little sensibility, unemotional (Charles’s stolid reaction to his wife’s funeral differed from the passion he showed at the time of her death.)"),
    ("strenuous", "kuch talab qiladigan, mashaqqatli", "C1", "57", "(adj.) requiring tremendous energy or stamina (Running a marathon is quite a strenuous task. So is watching an entire Star Trek marathon.)"),
    ("strident", "quloqni qomatga keltiruvchi, o'tkir (ovoz)", "C1", "57", "(adj.) harsh, loud (A strident man, Captain Von Trapp yelled at his daughter and made her cry.)"),
    ("stupefy", "karaxt qilmoq, esankiratmoq", "C1", "57", "(v.) to astonish, make insensible (Veronica’s audacity and ungratefulness stupefied her best friend, Heather.)"),
    ("stoic", "sabot bilan chidovchi, his bildirmas", "C1", "57", "(adj.) unaffected by passion or feeling (Penelope’s faithfulness to Odysseus required that she be stoic and put off her many suitors.)"),
    ("subjugate", "bo'ysundirmoq, qul qilmoq", "C1", "57", "(v.) to bring under control, subdue (The invading force captured and subjugated the natives of that place.)"),
    ("submissive", "itoatkor, bo'yin eguvchi", "C1", "57", "(adj.) easily yielding to authority (In some cultures, wives are supposed to be submissive and support their husbands in all matters.)"),
    ("succinct", "qisqa va aniq, lo'nda", "C1", "57", "(adj.) marked by compact precision (The governor’s succinct speech energized the crowd while the mayor’s rambled on and on.)"),
    ("superfluous", "ortiqcha, keraksiz", "C1", "57", "(adj.) exceeding what is necessary (Tracy had already won the campaign so her constant flattery of others was superfluous.)"),
    ("surfeit", "me'yordan ortiqlik, to'yib ketish", "C1", "57", "(n.) an overabundant supply or indulgence (After partaking of the surfeit of tacos and tamales at the All-You-Can-Eat Taco Tamale Lunch Special, Beth felt rather sick.)"),
    ("surmise", "taxmin qilmoq, faraz", "C1", "57", "(v.) to infer with little evidence (After speaking to only one of the students, the teacher was able to surmise what had caused the fight.)"),
    ("surreptitious", "yashirincha qilingan, pinhoniy", "C1", "57", "(adj.) stealthy (The surreptitious CIA agents were able to get in and out of the house without anyone noticing.)"),
    ("surrogate", "o'rinbosar, o'rnini bosuvchi", "C1", "57", "(n.) one acting in place of another (The surrogate carried the child to term for its biological parents.)"),
    ("swarthy", "qoramag'iz, bug'doyrang", "C1", "57", "(adj.) of dark color or complexion (When he got drunk, Robinson’s white skin became rather swarthy.)"),
    ("sycophant", "laganbardor, xushomadgo'y", "C1", "57", "(n.) one who flatters for self-gain (Some see the people in the cabinet as the president’s closest advisors, but others see them as sycophants.)"),
    ("tacit", "so'zsiz anglashilgan, indamay bildirilgan", "C1", "57", "(adj.) expressed without words (I interpreted my parents’ refusal to talk as a tacit acceptance of my request.)"),
    ("taciturn", "kamgap, indamas", "C1", "57", "(adj.) not inclined to talk (Though Jane never seems to stop talking, her brother is quite taciturn.)"),
    ("tangential", "mavzuga aloqasi uzoq, chetga chiquvchi", "C1", "57", "(adj.) incidental, peripheral, divergent (I tried to discuss my salary, but the boss kept veering off into tangential topics.)"),
    ("tantamount", "barobar, teng kuchli", "C1", "57", "(adj.) equivalent in value or significance (When it comes to sports, fearing your opponent is tantamount to losing.)"),
    ("tedious", "zerikarli, diqqinafas", "C1", "57", "(adj.) dull, boring (As time passed and the history professor continued to drone on and on, the lecture became increasingly tedious.)"),
    ("temerity", "haddan oshgan jur'at, betgachoparlik", "C1", "57", "(n.) audacity, recklessness (Tom and Huck entered the scary cave armed with nothing but their own temerity.)"),
    ("temperance", "me'yorni saqlash, o'zini tiyish", "C1", "57", "(n.) moderation in action or thought (Maintaining temperance will ensure that you are able to think rationally and objectively.)"),
    ("tenable", "himoya qilsa bo'ladigan, asosli", "C1", "57", "(adj.) able to be defended or maintained (The department heads tore down the arguments in other people’s theses, but Johari’s work proved to be quite tenable.)"),
    ("tenuous", "juda zaif, arang turgan", "C1", "57", "(adj.) having little substance or strength (Your argument is very tenuous, since it relies so much on speculation and hearsay.)"),
    ("terrestrial", "yerga oid, quruqlikdagi", "C1", "57", "(adj.) relating to the land (Elephants are terrestrial animals.)"),
    ("timorous", "yuraksiz, qo'rqoq", "C1", "57", "(adj.) timid, fearful (When dealing with the unknown, timorous Tallulah almost always broke into tears.)"),
    # ---- Unit 58 (C1) ----
    ("tirade", "achchiq uzun dashnom, po'pisali nutq", "C1", "58", "(n.) a long speech marked by harsh or biting language (Every time Jessica was late, her boyfriend went into a long tirade about punctuality.)"),
    ("toady", "laganbardor, yaltoqi", "C1", "58", "(n.) one who flatters in the hope of gaining favors (The other kids referred to the teacher’s pet as the Tenth Grade Toady.)"),
    ("tome", "katta qalin kitob", "C1", "58", "(n.) a large book (In college, I used to carry around an anatomy book that was the heaviest tome in my bag.)"),
    ("torpid", "karaxt, sust", "C1", "58", "(adj.) lethargic, dormant, lacking motion (The torpid whale floated, wallowing in the water for hours.)"),
    ("tortuous", "egri-bugri, chigal", "C1", "58", "(adj.) winding (The scary thing about driving in mountains are the narrow, tortuous roads.)"),
    ("tractable", "gapga kiruvchan, boshqarish oson", "C1", "58", "(adj.) easily controlled (The horse was so tractable, Myra didn’t even need a bridle.)"),
    ("tranquil", "sokin, osuda", "C1", "58", "(adj.) calm (There is a time of night when nothing moves and everything is tranquil.)"),
    ("transgress", "chegaradan chiqmoq, qoidani buzmoq", "C1", "58", "(v.) to violate, go over a limit (The criminal’s actions transgressed morality and human decency.)"),
    ("torrid", "jazirama; ehtirosli", "C1", "58", "(adj.) giving off intense heat, passionate (I didn’t want to witness the neighbor’s torrid affair through the window.)"),
    ("transient", "o'tkinchi, vaqtinchalik", "C1", "58", "(adj.) passing through briefly; passing into and out of existence (Because virtually everyone in Palm Beach is a tourist, the population of the town is quite transient.)"),
