def seed_vocab(db) -> int:
    """Yetishmayotgan so'zlarni qo'shadi. Idempotent: qayta ishga
    tushsa dublikat yaratmaydi, mavjudini o'zgartirmaydi.

    4000+ qator bo'lgani uchun bitta tranzaksiyada yoziladi — har
    so'zga alohida commit qilinsa serverless muhitda sekin bo'lardi."""
    import models
    have = {(row[0] or "").lower()
            for row in db.query(models.VocabWord.word).all()}
    added = 0
    for word, translation, level, unit, example in SEED_WORDS:
        if word.lower() in have:
            continue
        db.add(models.VocabWord(
            word=word, translation=translation, level=level,
            topic=f"Unit {unit}", example=example,
            is_active=1, created_by="JonyLugatBot"))
        have.add(word.lower())
        added += 1
    if added:
        db.commit()
    return added
